css:
.drt-league {
  width: 100%;
  height: var(--drt-league-h, 680px);
  container-type: inline-size;
  container-name: drt-league;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-league-bg);
  color: var(--drt-league-ink);
  font: 13px/1.45 var(--drt-league-sans);
  accent-color: var(--drt-league-accent);
  -webkit-font-smoothing: antialiased;
  --drt-league-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-league-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-league-out: cubic-bezier(.22, 1, .36, 1);
  --drt-league-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-league-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-league-focus, var(--drt-league-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-league__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-league__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-league__num, & .drt-league__tab { font-variant-numeric: tabular-nums; }
}
.drt-league__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-league-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-league-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-league__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-league-tipbg, color-mix(in oklch, var(--drt-league-ink) 94%, var(--drt-league-bg)));
  color: var(--drt-league-tipink, var(--drt-league-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-league-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-league__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-league__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-league__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-league__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-league-tipbg, color-mix(in oklch, var(--drt-league-ink) 94%, var(--drt-league-bg)));
  color: var(--drt-league-tipink, var(--drt-league-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-league-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --drt-league-a { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
.drt-league {
  /* re-theme with these four */
  --drt-league-bg: oklch(0.975 0.006 95);
  --drt-league-ink: oklch(0.24 0.022 258);
  --drt-league-accent: oklch(0.5 0.115 163);
  --drt-league-neg: oklch(0.57 0.165 32);
  /* derived */
  --drt-league-card: color-mix(in oklch, var(--drt-league-bg), white 70%);
  --drt-league-side: color-mix(in oklch, var(--drt-league-bg), var(--drt-league-ink) 4%);
  --drt-league-line: color-mix(in oklch, var(--drt-league-ink) 12%, transparent);
  --drt-league-hair: color-mix(in oklch, var(--drt-league-ink) 6.5%, transparent);
  --drt-league-mute: color-mix(in oklch, var(--drt-league-ink) 64%, var(--drt-league-bg));
  --drt-league-faint: color-mix(in oklch, var(--drt-league-ink) 44%, var(--drt-league-bg));
  --drt-league-pos: var(--drt-league-accent);
  --drt-league-rN: oklch(0.53 0.11 248);
  --drt-league-rM: oklch(0.67 0.13 72);
  --drt-league-rS: oklch(0.56 0.15 352);
  color-scheme: light;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--drt-league-line);
}
.drt-league__app { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }

/* ---------------------------------------------------------------- nav */
.drt-league__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 14px; background: var(--drt-league-side); border-right: 1px solid var(--drt-league-line); border-radius: 14px 0 0 14px; }
.drt-league__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .drt-league__logo { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: var(--drt-league-ink); color: var(--drt-league-bg); flex: none; }
  & :where(.drt-league__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 14px; font-weight: 750; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--drt-league-faint); }
}
.drt-league__navlist { display: grid; gap: 2px; }
.drt-league__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px;
  color: var(--drt-league-mute); font-weight: 560; text-align: left;
  transition: background-color .15s, color .15s;
  &:hover { background: color-mix(in oklch, var(--drt-league-ink) 6%, transparent); color: var(--drt-league-ink); }
  &[aria-current="page"] { background: var(--drt-league-card); color: var(--drt-league-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .06), inset 0 0 0 1px var(--drt-league-line); }
  &[aria-current="page"]::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--drt-league-ink); }
}
.drt-league__kl { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-league-faint); }
.drt-league__legend {
  display: grid; gap: 6px; padding: 0 6px;
  & .drt-league__lg { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--drt-league-mute); }
  & .drt-league__lg i { width: 9px; height: 9px; border-radius: 3px; background: var(--rc); }
  & .drt-league__lg em { margin-left: auto; font-style: normal; font-variant-numeric: tabular-nums; color: var(--drt-league-faint); }
}
.drt-league__navfoot {
  margin-top: auto; display: grid; gap: 6px; padding: 12px 8px 4px; border-top: 1px solid var(--drt-league-line);
  & b { font-size: 13px; font-weight: 650; font-variant-numeric: tabular-nums; }
}
.drt-league__export {
  margin-top: 6px; height: 32px; display: flex; align-items: center; justify-content: center; gap: 8px; border-radius: 8px;
  background: var(--drt-league-card); box-shadow: inset 0 0 0 1px var(--drt-league-line); font-weight: 600; font-size: 12.5px;
  transition: box-shadow .15s, translate .2s var(--drt-league-out);
  &:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--drt-league-ink) 30%, transparent); }
  &:active { translate: 0 1px; }
  & .drt-league__i { width: 16px; height: 16px; }
  &[aria-busy="true"] { color: var(--drt-league-faint); }
}

/* ---------------------------------------------------------------- top */
.drt-league__top { grid-area: top; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 16px 20px 12px; }
.drt-league__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-league-faint); font-variant-numeric: tabular-nums; }
.drt-league__title h2 { font-size: clamp(19px, 2.1cqi, 25px); font-weight: 760; letter-spacing: -.028em; line-height: 1.1; margin-top: 3px; }
.drt-league__ctrls { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.drt-league__seg, .drt-league__chips {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: color-mix(in oklch, var(--drt-league-ink) 6%, transparent);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 580; color: var(--drt-league-mute); display: flex; align-items: center; gap: 6px; white-space: nowrap; transition: background-color .15s, color .15s, box-shadow .15s; }
  & button:hover { color: var(--drt-league-ink); }
  & button[aria-checked="true"] { background: var(--drt-league-card); color: var(--drt-league-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .08), inset 0 0 0 1px var(--drt-league-line); }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--rc); }
}

/* ---------------------------------------------------------------- main + league layout */
.drt-league__main { grid-area: main; min-height: 0; padding: 0 20px 18px; overflow: hidden; }
.drt-league__view { height: 100%; }
.drt-league__lv {
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1.06fr) minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "table bump" "table focus";
}
.drt-league__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.drt-league__kpi {
  display: grid; gap: 1px; padding: 10px 14px 11px; border-radius: 12px; background: var(--drt-league-card); box-shadow: inset 0 0 0 1px var(--drt-league-line);
  & .drt-league__kv { font-size: clamp(18px, 2cqi, 23px); font-weight: 720; letter-spacing: -.025em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & .drt-league__ks { font-size: 11.5px; color: var(--drt-league-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .drt-league__ks b { font-weight: 650; }
  & .is-pos { color: var(--drt-league-pos); }
  & .is-neg { color: var(--drt-league-neg); }
}
.drt-league__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-league-card); box-shadow: inset 0 0 0 1px var(--drt-league-line); overflow: hidden; }
.drt-league__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 11px 14px 8px;
  & h3 { font-size: 13px; font-weight: 680; letter-spacing: -.01em; }
  & h3 small { font-weight: 500; color: var(--drt-league-faint); margin-left: 6px; font-size: 11.5px; }
}
.drt-league__tablep { grid-area: table; }
.drt-league__bumpp { grid-area: bump; }
.drt-league__focusp { grid-area: focus; }

/* ---------------------------------------------------------------- table (subgrid rows) */
.drt-league__tw { flex: 1; min-height: 0; padding: 0 6px 6px; }
.drt-league__tbl {
  display: grid; min-width: 500px;
  grid-template-columns: 50px minmax(140px, 1.8fr) 66px minmax(92px, 1fr) 52px 64px;
  column-gap: 8px;
}
.drt-league__thead, .drt-league__tbody, .drt-league__tr { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
.drt-league__thead { position: sticky; top: 0; z-index: 2; background: var(--drt-league-card); }
.drt-league__th {
  padding: 0 8px; height: 30px; align-items: center; border-bottom: 1px solid var(--drt-league-line);
  & span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-league-faint); }
  & button { display: inline-flex; align-items: center; gap: 4px; text-transform: inherit; letter-spacing: inherit; font-weight: inherit; border-radius: 4px; }
  & button:hover { color: var(--drt-league-ink); }
  & [aria-sort="ascending"] button, & [aria-sort="descending"] button { color: var(--drt-league-ink); }
  & [aria-sort="ascending"] button::after { content: ""; border: 4px solid transparent; border-bottom: 5px solid currentColor; translate: 0 -2px; }
  & [aria-sort="descending"] button::after { content: ""; border: 4px solid transparent; border-top: 5px solid currentColor; translate: 0 2px; }
  & .drt-league__r { text-align: right; justify-self: end; }
}
.drt-league__row {
  position: relative; padding: 0 8px; min-height: 42px; align-items: center; border-radius: 8px; cursor: pointer;
  transition: background-color .15s, opacity .45s var(--drt-league-out) calc(var(--i, 0) * 32ms), translate .55s var(--drt-league-out) calc(var(--i, 0) * 32ms);
  @starting-style { opacity: 0; translate: 0 8px; }
  &:not(:last-child)::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: 0; height: 1px; background: var(--drt-league-hair); }
  &:hover { background: color-mix(in oklch, var(--drt-league-ink) 4%, transparent); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--rc) 11%, var(--drt-league-card)); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 8px; bottom: 8px; width: 3px; border-radius: 3px; background: var(--rc); }
  &:focus-visible { outline-offset: -2px; }
  & > span { min-width: 0; font-variant-numeric: tabular-nums; }
  & .drt-league__r { text-align: right; }
}
.drt-league__rk {
  display: flex; align-items: center; gap: 6px;
  & b { width: 22px; font-size: 15px; font-weight: 740; letter-spacing: -.02em; }
  & i { display: inline-flex; align-items: center; font-style: normal; font-size: 10.5px; font-weight: 650; gap: 1px; }
  & i svg { width: 9px; height: 9px; fill: currentColor; }
  & .up { color: var(--drt-league-pos); }
  & .dn { color: var(--drt-league-neg); }
  & .dn svg { rotate: 180deg; }
  & .eq { color: var(--drt-league-faint); }
}
.drt-league__st {
  display: grid; line-height: 1.2;
  & b { font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--drt-league-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small::before { content: ""; display: inline-block; width: 7px; height: 7px; border-radius: 2px; background: var(--rc); margin-right: 5px; }
}
.drt-league__vt {
  display: grid; grid-template-columns: minmax(0, 1fr) 46px; align-items: center; gap: 8px;
  & em { font-style: normal; text-align: right; font-weight: 620; font-size: 12px; }
}
.drt-league__bar {
  position: relative; height: 10px; border-radius: 3px; background: linear-gradient(90deg, transparent calc(50% - .5px), var(--drt-league-faint) 0 calc(50% + .5px), transparent 0), color-mix(in oklch, var(--drt-league-ink) 5%, transparent);
  & i { position: absolute; top: 1px; bottom: 1px; left: 50%; width: 50%; border-radius: 0 2px 2px 0; background: var(--drt-league-pos); transform-origin: 0 50%; scale: var(--w, 0) 1; transition: scale .7s var(--drt-league-out); }
  & i.neg { left: 0; border-radius: 2px 0 0 2px; background: var(--drt-league-neg); transform-origin: 100% 50%; }
}
.drt-league__lfl.is-pos { color: var(--drt-league-pos); }
.drt-league__lfl.is-neg { color: var(--drt-league-neg); }
.drt-league__spark svg { width: 64px; height: 24px; }
.drt-league__spark .b { stroke: var(--drt-league-line); stroke-dasharray: 2 2; }
.drt-league__spark .l { fill: none; stroke: var(--rc); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
.drt-league__spark .d { fill: var(--rc); }

/* ---------------------------------------------------------------- bump chart */
.drt-league__bumpbox, .drt-league__wbox { position: relative; flex: 1; min-height: 0; margin: 0 6px 6px; }
.drt-league__bump, .drt-league__weeks { position: absolute; inset: 0; width: 100%; height: 100%; }
.drt-league__bump {
  & .gl { stroke: var(--drt-league-hair); }
  & .ax { font-size: 10px; fill: var(--drt-league-faint); font-variant-numeric: tabular-nums; }
  & .drt-league__ln { cursor: pointer; transition: opacity .3s; }
  & .drt-league__ln .v { fill: none; stroke: var(--rc); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: d .75s var(--drt-league-out), stroke-width .2s; }
  & .drt-league__ln .h { fill: none; stroke: transparent; stroke-width: 12; transition: d .75s var(--drt-league-out); }
  & .drt-league__ln .end { transition: transform .75s var(--drt-league-out); }
  & .drt-league__ln .end circle { fill: var(--drt-league-card); stroke: var(--rc); stroke-width: 2; }
  & .drt-league__ln .beg { transition: transform .75s var(--drt-league-out); }
  & .drt-league__ln .beg circle { fill: var(--rc); }
  & .drt-league__ln text { font-size: 10.5px; font-weight: 600; fill: var(--drt-league-mute); }
  & .drt-league__ln.is-sel .v { stroke-width: 3.6; }
  & .drt-league__ln.is-sel text { fill: var(--drt-league-ink); font-weight: 750; }
  & .drt-league__ln.is-out { opacity: 0; pointer-events: none; }
  &:not(:has(.drt-league__ln:hover)) .drt-league__ln:not(.is-sel):not(.is-out) { opacity: .42; }
  &:has(.drt-league__ln:hover) .drt-league__ln:not(:hover):not(.is-out) { opacity: .16; }
  &:has(.drt-league__ln:hover) .drt-league__ln:hover .v { stroke-width: 3.6; }
  &.is-enter .drt-league__ln .v { stroke-dasharray: 1; stroke-dashoffset: 1; animation: drt-league-draw 1.1s var(--drt-league-out) calc(var(--i) * 45ms) forwards; }
  &.is-enter .drt-league__ln .end, &.is-enter .drt-league__ln .beg { animation: drt-league-pop .5s var(--drt-league-snap) calc(400ms + var(--i) * 45ms) backwards; }
  &.is-still * { transition: none !important; }
}
@keyframes drt-league-draw { to { stroke-dashoffset: 0; } }
@keyframes drt-league-pop { from { opacity: 0; } }

/* ---------------------------------------------------------------- focus panel */
.drt-league__fh {
  align-items: center;
  & h3 { font-size: 14.5px; font-weight: 720; letter-spacing: -.02em; }
}
.drt-league__fbadge { font-size: 11px; font-weight: 650; padding: 3px 8px; border-radius: 99px; background: color-mix(in oklch, var(--rc, var(--drt-league-ink)) 14%, transparent); color: color-mix(in oklch, var(--rc, var(--drt-league-ink)) 75%, var(--drt-league-ink)); white-space: nowrap; font-variant-numeric: tabular-nums; }
.drt-league__fstats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; padding: 0 14px 6px;
  & div { display: grid; }
  & dt { font-size: 10.5px; color: var(--drt-league-faint); text-transform: uppercase; letter-spacing: .06em; font-weight: 600; }
  & dd { font-size: 14px; font-weight: 680; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
  & .is-pos { color: var(--drt-league-pos); }
  & .is-neg { color: var(--drt-league-neg); }
}
.drt-league__weeks {
  cursor: crosshair;
  & .gl { stroke: var(--drt-league-hair); }
  & .ax { font-size: 10px; fill: var(--drt-league-faint); font-variant-numeric: tabular-nums; }
  & .bar { fill: color-mix(in oklch, var(--rc) 70%, var(--drt-league-card)); transform-box: fill-box; transform-origin: 50% 100%; animation: drt-league-grow .6s var(--drt-league-out) calc(var(--i) * 22ms) backwards; }
  & .bar.miss { fill: color-mix(in oklch, var(--rc) 32%, var(--drt-league-card)); }
  & .tg { stroke: var(--drt-league-ink); stroke-width: 2; stroke-linecap: round; }
  & .xh { fill: color-mix(in oklch, var(--drt-league-ink) 7%, transparent); opacity: 0; }
  & .xh.is-on { opacity: 1; }
}
@keyframes drt-league-grow { from { scale: 1 0; } }

/* ---------------------------------------------------------------- managers */
.drt-league__mv { display: flex; flex-direction: column; gap: 12px; }
.drt-league__mintro { font-size: 12.5px; color: var(--drt-league-mute); max-width: 72ch; }
.drt-league__mgrs { flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.drt-league__mgr {
  --drt-league-a: 0deg;
