const ST = [
  ['LDS', 'Leeds Briggate', 'N', 88], ['YRK', 'York Coney Street', 'N', 64], ['HGT', 'Harrogate James Street', 'N', 57], ['NCL', 'Newcastle Grey Street', 'N', 92], ['DUR', 'Durham Saddler Street', 'N', 41],
  ['BHM', 'Birmingham Colmore Row', 'M', 96], ['NOT', 'Nottingham Bridlesmith Gate', 'M', 79], ['LEI', 'Leicester High Cross', 'M', 61], ['DBY', 'Derby Sadler Gate', 'M', 47],
  ['BTH', 'Bath Milsom Street', 'S', 72], ['BRS', 'Bristol Park Street', 'S', 85], ['BTN', 'Brighton North Laine', 'S', 77], ['GLD', 'Guildford High Street', 'S', 69], ['WIN', 'Winchester Parchment Street', 'S', 52]
