  const narrow = g.W < 300, wide = g.W > 420;
  D.rows.forEach((r, idx) => {
    let el = lineEls.get(r.s.code);
    if (!el) {
      el = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      el.setAttribute('class', 'drt-league__ln');
      el.dataset.code = r.s.code;
