      el.style.setProperty('--i', idx);
      el.innerHTML = '<path class="h"/><path class="v" pathLength="1"/><g class="beg"><circle r="3"/></g><g class="end"><circle r="4"/><text x="9" y="3.6"></text></g>';
      bumpSvg.appendChild(el);
      lineEls.set(r.s.code, el);
    }
    const pts = r.hist.map((rk, i) => [g.X(i), g.Y(rk)]);
    const d = bumpPath(pts);
    setD(el.querySelector('.v'), d); setD(el.querySelector('.h'), d);
    if (!HAS_D) { el.querySelector('.v').setAttribute('d', d); el.querySelector('.h').setAttribute('d', d); }
    el.querySelector('.beg').style.transform = 'translate(' + pts[0][0] + 'px,' + pts[0][1] + 'px)';
    el.querySelector('.end').style.transform = 'translate(' + pts[7][0] + 'px,' + pts[7][1] + 'px)';
    el.querySelector('text').textContent = narrow ? r.s.code : wide ? r.s.short + ' ' + pct(r.vt, 0) : r.s.short;
