bumpSvg.addEventListener('pointerleave', untip);
bumpSvg.addEventListener('click', e => { const ln = e.target.closest('.drt-league__ln'); if (ln) select(ln.dataset.code); });

/* ================================================================ focus panel */
const wSvg = $('.drt-league__weeks'), wBox = $('.drt-league__wbox');
let wGeo = null;
const renderFocus = () => {
  const r = D.rows.find(x => x.s.code === sel); if (!r) return;
  const p = $('.drt-league__focusp');
