  $('[data-out="fname"]').textContent = r.s.name;
  $('[data-out="fbadge"]').textContent = 'Rank ' + r.rank + ' of 14 · ' + REG[r.s.reg].m;
  const f = k => $('[data-f="' + k + '"]');
