    s += '<line class="tg" x1="' + (x0 - 1).toFixed(1) + '" x2="' + (x0 + w + 1).toFixed(1) + '" y1="' + Y(x.target).toFixed(1) + '" y2="' + Y(x.target).toFixed(1) + '"/>';
