          '<div class="drt-league__mtop"><div class="ring" role="img"><b></b><small>to target</small></div><dl><div><dt>Sales</dt><dd data-m="s"></dd></div><div><dt>Target</dt><dd data-m="t"></dd></div><div><dt>LFL</dt><dd data-m="lfl"></dd></div><div><dt>At target</dt><dd data-m="hit"></dd></div></dl></div>' +
