css:
.drt-footfall {
  width: 100%;
  height: var(--drt-footfall-h, 680px);
  container-type: inline-size;
  container-name: drt-footfall;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-footfall-bg);
  color: var(--drt-footfall-ink);
  font: 13px/1.45 var(--drt-footfall-sans);
  accent-color: var(--drt-footfall-accent);
  -webkit-font-smoothing: antialiased;
  --drt-footfall-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-footfall-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-footfall-out: cubic-bezier(.22, 1, .36, 1);
  --drt-footfall-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-footfall-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-footfall-focus, var(--drt-footfall-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-footfall__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-footfall__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-footfall__num, & .drt-footfall__tab { font-variant-numeric: tabular-nums; }
}
.drt-footfall__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-footfall-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-footfall-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-footfall__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-footfall-tipbg, color-mix(in oklch, var(--drt-footfall-ink) 94%, var(--drt-footfall-bg)));
  color: var(--drt-footfall-tipink, var(--drt-footfall-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-footfall-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-footfall__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-footfall__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-footfall__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-footfall__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-footfall-tipbg, color-mix(in oklch, var(--drt-footfall-ink) 94%, var(--drt-footfall-bg)));
  color: var(--drt-footfall-tipink, var(--drt-footfall-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-footfall-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --drt-footfall-p { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
.drt-footfall {
  /* re-theme with these four */
  --drt-footfall-bg: oklch(0.205 0.012 62);
  --drt-footfall-ink: oklch(0.95 0.012 85);
  --drt-footfall-accent: oklch(0.83 0.115 80);
  --drt-footfall-tx: oklch(0.7 0.165 34);
  /* derived */
  --drt-footfall-ff: var(--drt-footfall-accent);
  --drt-footfall-cv: oklch(0.85 0.1 168);
  --drt-footfall-card: color-mix(in oklch, var(--drt-footfall-bg), var(--drt-footfall-ink) 4.5%);
  --drt-footfall-side: color-mix(in oklch, var(--drt-footfall-bg), black 18%);
  --drt-footfall-line: color-mix(in oklch, var(--drt-footfall-ink) 11%, transparent);
  --drt-footfall-hair: color-mix(in oklch, var(--drt-footfall-ink) 6%, transparent);
  --drt-footfall-mute: color-mix(in oklch, var(--drt-footfall-ink) 66%, var(--drt-footfall-bg));
  --drt-footfall-faint: color-mix(in oklch, var(--drt-footfall-ink) 44%, var(--drt-footfall-bg));
  --drt-footfall-good: oklch(0.8 0.13 150);
  --drt-footfall-bad: oklch(0.72 0.15 28);
  color-scheme: dark;
  border-radius: 14px;
}
.drt-footfall__app { height: 100%; display: grid; grid-template-columns: 184px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }

/* ---------------------------------------------------------------- nav */
.drt-footfall__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--drt-footfall-side); border-radius: 14px 0 0 14px; }
.drt-footfall__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .drt-footfall__logo { width: 32px; height: 32px; border-radius: 50% 50% 6px 6px; display: grid; place-items: center; background: var(--drt-footfall-accent); color: var(--drt-footfall-bg); flex: none; }
  & :where(.drt-footfall__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 15px; font-weight: 700; letter-spacing: .02em; }
  & small { font-size: 11px; color: var(--drt-footfall-faint); }
}
.drt-footfall__navlist { display: grid; gap: 2px; }
.drt-footfall__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px;
  color: var(--drt-footfall-mute); font-weight: 560; text-align: left; transition: background-color .15s, color .15s;
  &:hover { background: color-mix(in oklch, var(--drt-footfall-ink) 6%, transparent); color: var(--drt-footfall-ink); }
  &[aria-current="page"] { background: color-mix(in oklch, var(--drt-footfall-accent) 14%, transparent); color: var(--drt-footfall-accent); }
}
.drt-footfall__kl { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--drt-footfall-faint); }
.drt-footfall__key {
  display: grid; gap: 7px; padding: 0 6px; font-size: 12px; color: var(--drt-footfall-mute);
  & span:not(.drt-footfall__kl) { display: flex; align-items: center; gap: 8px; }
  & i { width: 12px; height: 9px; border-radius: 2px; }
  & .ff { background: color-mix(in oklch, var(--drt-footfall-ff) 34%, transparent); box-shadow: inset 0 0 0 1.5px var(--drt-footfall-ff); }
  & .tx { background: var(--drt-footfall-tx); width: 7px; margin: 0 2.5px; }
  & .cv { height: 2px; background: var(--drt-footfall-cv); position: relative; }
  & .cv::after { content: ""; position: absolute; left: 3px; top: -3px; width: 6px; height: 6px; border-radius: 50%; background: var(--drt-footfall-cv); }
  & .lw { height: 0; border-top: 2px dashed var(--drt-footfall-ink); opacity: .7; border-radius: 0; }
}
.drt-footfall__health {
  margin-top: auto; display: grid; gap: 4px; padding: 12px 8px 2px; border-top: 1px solid var(--drt-footfall-line);
  & .drt-footfall__hl { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
  & .drt-footfall__hl i { width: 8px; height: 8px; border-radius: 50%; background: var(--drt-footfall-good); box-shadow: 0 0 0 3px color-mix(in oklch, var(--drt-footfall-good) 22%, transparent); }
  & b { font-weight: 600; }
  & small { font-size: 11px; color: var(--drt-footfall-faint); }
}

/* ---------------------------------------------------------------- top */
.drt-footfall__top { grid-area: top; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 16px; align-items: end; padding: 16px 20px 12px; }
.drt-footfall__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-footfall-faint); }
.drt-footfall__title h2 { font-size: clamp(19px, 2.1cqi, 25px); font-weight: 720; letter-spacing: -.025em; line-height: 1.12; margin-top: 3px; }
.drt-footfall__title h2 span { color: var(--drt-footfall-accent); }
.drt-footfall__ctrls { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.drt-footfall__seg, .drt-footfall__days {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--drt-footfall-ink) 6%, transparent);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 580; color: var(--drt-footfall-mute); white-space: nowrap; font-variant-numeric: tabular-nums; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--drt-footfall-ink); }
  & button[aria-checked="true"] { background: var(--drt-footfall-ink); color: var(--drt-footfall-bg); }
}
.drt-footfall__days {
  grid-column: 1 / -1; justify-self: start; overflow-x: auto; max-width: 100%; scrollbar-width: none;
  & button { display: grid; justify-items: center; line-height: 1.05; height: 38px; padding: 0 12px; }
  & button small { font-size: 10px; font-weight: 500; opacity: .7; }
  & button[data-v="w"] { margin-left: 6px; }
}
.drt-footfall__switch {
  display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px 0 6px; border-radius: 10px; font-size: 12.5px; font-weight: 580; color: var(--drt-footfall-mute);
  background: color-mix(in oklch, var(--drt-footfall-ink) 6%, transparent);
  & .drt-footfall__knob { width: 30px; height: 18px; border-radius: 99px; background: color-mix(in oklch, var(--drt-footfall-ink) 18%, transparent); position: relative; transition: background-color .2s; }
  & .drt-footfall__knob::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--drt-footfall-ink); transition: translate .32s var(--drt-footfall-spring); }
  &[aria-checked="true"] { color: var(--drt-footfall-ink); }
  &[aria-checked="true"] .drt-footfall__knob { background: var(--drt-footfall-accent); }
  &[aria-checked="true"] .drt-footfall__knob::after { translate: 12px 0; background: var(--drt-footfall-bg); }
}

/* ---------------------------------------------------------------- main */
.drt-footfall__main { grid-area: main; min-height: 0; padding: 0 20px 18px; overflow: hidden; }
.drt-footfall__view { height: 100%; }
.drt-footfall__hv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "kpis kpis" "chart fun"; }
.drt-footfall__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.drt-footfall__kpi {
  position: relative; display: grid; padding: 10px 14px 11px; border-radius: 12px; background: var(--drt-footfall-card); overflow: hidden;
  &::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c, transparent); }
  & b { font-size: clamp(19px, 2.1cqi, 25px); font-weight: 700; letter-spacing: -.025em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & span:last-child { font-size: 11.5px; color: var(--drt-footfall-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .up { color: var(--drt-footfall-good); }
  & .dn { color: var(--drt-footfall-bad); }
}
.drt-footfall__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-footfall-card); overflow: hidden; }
.drt-footfall__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 12px 16px 6px;
  & h3 { font-size: 13px; font-weight: 650; }
  & h3 small { font-weight: 500; color: var(--drt-footfall-faint); margin-left: 6px; font-size: 11.5px; }
}
.drt-footfall__hint { font-size: 11px; color: var(--drt-footfall-faint); }
.drt-footfall__chartp { grid-area: chart; }
.drt-footfall__funp { grid-area: fun; }

/* ---------------------------------------------------------------- hourly chart (HTML bars, svg line) */
.drt-footfall__chart { flex: 1; min-height: 0; display: grid; grid-template-columns: 40px minmax(0, 1fr) 40px; padding: 10px 6px 30px; }
.drt-footfall__yl, .drt-footfall__yr { position: relative; font-size: 10.5px; color: var(--drt-footfall-faint); font-variant-numeric: tabular-nums; }
.drt-footfall__yl span, .drt-footfall__yr span { position: absolute; translate: 0 50%; }
.drt-footfall__yl span { right: 8px; }
.drt-footfall__yr span { left: 8px; color: color-mix(in oklch, var(--drt-footfall-cv) 75%, var(--drt-footfall-bg)); }
.drt-footfall__plot { position: relative; min-height: 0; }
.drt-footfall__grid i { position: absolute; left: 0; right: 0; height: 1px; background: var(--drt-footfall-hair); }
.drt-footfall__grid i:first-child { background: var(--drt-footfall-line); }
.drt-footfall__cols { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(11, minmax(0, 1fr)); }
.drt-footfall__col {
  position: relative; height: 100%; border-radius: 6px; cursor: pointer;
  transition: background-color .2s;
  &:hover, &:focus-visible { background: color-mix(in oklch, var(--drt-footfall-ink) 5%, transparent); }
  &:focus-visible { outline-offset: -2px; }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--drt-footfall-accent) 11%, transparent); }
  &[aria-pressed="true"] .lab { color: var(--drt-footfall-accent); font-weight: 700; }
  & > span { position: absolute; pointer-events: none; }
  & .ff, & .tx { bottom: 0; top: 0; left: 50%; translate: -50% 0; border-radius: 4px 4px 1px 1px;
    transition: clip-path .7s var(--drt-footfall-out) calc(var(--i) * 38ms); }
  & .ff { width: 62%; background: linear-gradient(color-mix(in oklch, var(--drt-footfall-ff) 34%, transparent), color-mix(in oklch, var(--drt-footfall-ff) 16%, transparent)); box-shadow: inset 0 2.5px 0 var(--drt-footfall-ff); clip-path: inset(calc((1 - var(--f)) * 100%) 0 0 0); }
  & .tx { width: 30%; background: var(--drt-footfall-tx); clip-path: inset(calc((1 - var(--t)) * 100%) 0 0 0); }
  & .lw { left: 14%; right: 14%; top: 0; height: 100%; translate: 0 calc((1 - var(--g)) * 100%); border-top: 2px dashed color-mix(in oklch, var(--drt-footfall-ink) 75%, transparent); opacity: 0; transition: translate .7s var(--drt-footfall-out) calc(var(--i) * 38ms), opacity .3s; }
  & .cv { left: 0; right: 0; top: 0; height: 100%; translate: 0 calc((1 - var(--c)) * 100%); transition: translate .7s var(--drt-footfall-out) calc(var(--i) * 38ms); z-index: 2; }
  & .cv::before { content: ""; position: absolute; left: 50%; top: -4.5px; width: 9px; height: 9px; margin-left: -4.5px; border-radius: 50%; background: var(--drt-footfall-card); box-shadow: inset 0 0 0 2.5px var(--drt-footfall-cv); }
  & .lab { left: 0; right: 0; bottom: -22px; text-align: center; font-size: 10.5px; color: var(--drt-footfall-faint); font-variant-numeric: tabular-nums; }
  @starting-style {
    & .ff, & .tx { clip-path: inset(100% 0 0 0); }
    & .cv { translate: 0 100%; }
  }
}
.drt-footfall__plot:has(.drt-footfall__col[aria-pressed="true"]) .drt-footfall__col:not([aria-pressed="true"]) .ff { background: color-mix(in oklch, var(--drt-footfall-ff) 14%, transparent); box-shadow: inset 0 2px 0 color-mix(in oklch, var(--drt-footfall-ff) 50%, transparent); }
.drt-footfall:has(.drt-footfall__switch[aria-checked="true"]) .drt-footfall__col .lw { opacity: 1; }
.drt-footfall__line {
  position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 1;
  clip-path: inset(0 0 0 0); transition: clip-path 1.1s var(--drt-footfall-out) .25s;
  @starting-style { clip-path: inset(0 100% 0 0); }
  & path { transition: d .7s var(--drt-footfall-out); }
  & .l { fill: none; stroke: var(--drt-footfall-cv); stroke-width: 2.25; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
  & .a { fill: color-mix(in oklch, var(--drt-footfall-cv) 4%, transparent); }
}

/* ---------------------------------------------------------------- funnel */
.drt-footfall__unpin { font-size: 11.5px; font-weight: 600; color: var(--drt-footfall-accent); padding: 2px 6px; border-radius: 6px; }
.drt-footfall__unpin:hover { background: color-mix(in oklch, var(--drt-footfall-accent) 12%, transparent); }
.drt-footfall__stages { display: grid; gap: 14px; padding: 8px 16px 14px; }
.drt-footfall__stage {
  display: grid; grid-template-columns: 1fr auto; gap: 4px 10px; align-items: baseline;
  & .lbl { font-size: 12px; color: var(--drt-footfall-mute); }
  & b { font-size: 20px; font-weight: 700; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & .trk { grid-column: 1 / -1; height: 8px; border-radius: 4px;
    background: linear-gradient(90deg, var(--c, var(--drt-footfall-ink)) var(--drt-footfall-p), color-mix(in oklch, var(--drt-footfall-ink) 8%, transparent) 0);
    transition: --drt-footfall-p .9s var(--drt-footfall-out); }
  &[data-st="pass"] .trk { --c: color-mix(in oklch, var(--drt-footfall-ink) 30%, transparent); }
  & em { grid-column: 1 / -1; font-style: normal; font-size: 11.5px; color: var(--drt-footfall-faint); font-variant-numeric: tabular-nums; }
  & em b { font-size: inherit; font-weight: 650; color: var(--drt-footfall-ink); letter-spacing: 0; }
}
.drt-footfall__stage + .drt-footfall__stage { position: relative; }
.drt-footfall__opp {
  margin: auto 12px 12px; padding: 12px 14px; border-radius: 10px; display: grid; gap: 6px;
  background: color-mix(in oklch, var(--drt-footfall-tx) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--drt-footfall-tx) 22%, transparent);
  & .drt-footfall__opptx { font-size: 12.5px; line-height: 1.45; color: var(--drt-footfall-mute); text-wrap: pretty; }
  & .drt-footfall__opptx b { color: var(--drt-footfall-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
}
.drt-footfall__flag {
  justify-self: start; display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 620;
  background: var(--drt-footfall-tx); color: oklch(0.2 0.03 30); transition: filter .15s, background-color .2s;
  & .drt-footfall__i { width: 15px; height: 15px; }
  &:hover { filter: brightness(1.08); }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--drt-footfall-ink) 12%, transparent); color: var(--drt-footfall-ink); }
}

/* ---------------------------------------------------------------- week grid */
.drt-footfall__gv { display: flex; flex-direction: column; }
.drt-footfall__gridp { flex: 1; }
.drt-footfall__glegend {
  display: flex; align-items: center; gap: 8px; font-size: 10.5px; color: var(--drt-footfall-faint); font-variant-numeric: tabular-nums;
  & i { width: 120px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, color-mix(in oklch, var(--drt-footfall-lo), var(--drt-footfall-cv) 8%), var(--drt-footfall-cv)); }
}
.drt-footfall { --drt-footfall-lo: oklch(0.29 0.03 172); }
@supports (color: oklch(from red l c h)) { .drt-footfall { --drt-footfall-lo: oklch(from var(--drt-footfall-cv) 0.29 calc(c * .3) h); } }
.drt-footfall__gwrap { flex: 1; min-height: 0; padding: 4px 16px 16px; }
.drt-footfall__wgrid { display: grid; grid-template-columns: 74px repeat(11, minmax(38px, 1fr)) 84px; grid-template-rows: auto repeat(7, minmax(36px, 1fr)); gap: 4px; min-width: 640px; height: 100%; }
.drt-footfall__gh { font-size: 10.5px; color: var(--drt-footfall-faint); text-align: center; align-self: end; padding-bottom: 2px; font-variant-numeric: tabular-nums; }
.drt-footfall__gd { display: grid; align-content: center; font-size: 12px; font-weight: 620; line-height: 1.2; }
.drt-footfall__gd small { font-size: 10.5px; font-weight: 500; color: var(--drt-footfall-faint); }
.drt-footfall__gt { display: grid; align-content: center; justify-items: end; font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums; line-height: 1.2; }
.drt-footfall__gt small { font-size: 10.5px; font-weight: 500; color: var(--drt-footfall-faint); }
.drt-footfall__cell {
  position: relative; min-height: 36px; border-radius: 7px; display: grid; place-items: center; cursor: pointer;
  background: color-mix(in oklch, var(--drt-footfall-lo), var(--drt-footfall-cv) calc(8% + var(--q) * 92%));
  opacity: 1; scale: 1;
  transition: opacity .4s var(--drt-footfall-out) calc((var(--r) + var(--h)) * 22ms), scale .5s var(--drt-footfall-snap) calc((var(--r) + var(--h)) * 22ms), box-shadow .15s, background-color .5s;
  @starting-style { opacity: 0; scale: .6; }
  & i { width: calc(5px + var(--s) * 20px); aspect-ratio: 1; border-radius: 50%; background: color-mix(in oklch, var(--drt-footfall-ink), var(--drt-footfall-bg) calc(var(--q) * 100%)); opacity: .82; transition: width .5s var(--drt-footfall-out); }
  &:hover { box-shadow: 0 0 0 2px var(--drt-footfall-ink); z-index: 1; }
  &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--drt-footfall-bg), 0 0 0 4px var(--drt-footfall-accent); z-index: 1; }
  &:focus-visible { outline-offset: 3px; }
}

/* ---------------------------------------------------------------- container: rail */
@container drt-footfall (max-width: 960px) {
  .drt-footfall__app { grid-template-columns: 64px minmax(0, 1fr); }
  .drt-footfall__nav { padding: 16px 10px; align-items: center; }
  .drt-footfall__brandtx, .drt-footfall__navbtn span, .drt-footfall__key, .drt-footfall__health small, .drt-footfall__health .drt-footfall__kl, .drt-footfall__health b { display: none; }
  .drt-footfall__health { border: 0; padding: 0; }
  .drt-footfall__brand { padding: 0; }
  .drt-footfall__navbtn { width: 44px; justify-content: center; padding: 0; }
  .drt-footfall__main { overflow: auto; }
  .drt-footfall__view { height: auto; }
  .drt-footfall__hv { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 380px auto; grid-template-areas: "kpis" "chart" "fun"; }
  .drt-footfall__funp { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto 1fr; }
  .drt-footfall__funp .drt-footfall__ph { grid-column: 1 / -1; }
  .drt-footfall__opp { margin: 8px 12px 14px; }
  .drt-footfall__gridp { height: 460px; }
}
/* ---------------------------------------------------------------- container: stacked */
@container drt-footfall (max-width: 760px) {
  .drt-footfall__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "nav" "top" "main"; }
  .drt-footfall__nav { flex-direction: row; align-items: center; padding: 10px 14px; gap: 10px; border-radius: 14px 14px 0 0; }
  .drt-footfall__brandtx { display: grid; }
  .drt-footfall__navlist { display: flex; gap: 4px; margin-left: auto; }
  .drt-footfall__navbtn { width: auto; padding: 0 10px; }
  .drt-footfall__navbtn span { display: inline; }
  .drt-footfall__health { margin: 0; }
  .drt-footfall__top { grid-template-columns: minmax(0, 1fr); padding: 12px 14px 10px; }
  .drt-footfall__ctrls { justify-content: flex-start; }
  .drt-footfall__main { padding: 0 14px 14px; }
  .drt-footfall__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .drt-footfall__hv { grid-template-rows: auto 320px auto; }
  .drt-footfall__funp { grid-template-columns: minmax(0, 1fr); }
  .drt-footfall__hint { display: none; }
}
@container drt-footfall (max-width: 480px) {
  .drt-footfall__navbtn span, .drt-footfall__brandtx small { display: none; }
  .drt-footfall__navbtn { width: 40px; padding: 0; justify-content: center; }
  .drt-footfall__seg button { padding: 0 8px; font-size: 12px; }
  .drt-footfall__days button { padding: 0 8px; }
