const STORES = [
  { name: 'Canal Street', pass: 360, cap: .118, conv: .33, atv: 74 },
  { name: 'Merchant Quarter', pass: 520, cap: .088, conv: .29, atv: 61 },
  { name: 'Riverside Arcade', pass: 240, cap: .152, conv: .37, atv: 88 }
