/* ---------------------------------------------------------------- week */
.drt-staffing__wv { display: flex; flex-direction: column; }
.drt-staffing__weekp { flex: 1; }
.drt-staffing__wl { display: flex; align-items: center; gap: 8px; font-size: 10.5px; color: var(--drt-staffing-faint);
