.drt-staffing__wwrap { flex: 1; min-height: 0; padding: 4px 16px 16px; }
.drt-staffing__wgrid { display: grid; grid-template-columns: 92px repeat(15, minmax(30px, 1fr)) 104px; grid-template-rows: auto repeat(7, minmax(40px, 1fr)); gap: 3px; min-width: 700px; height: 100%; }
.drt-staffing__wh { font-size: 10.5px; color: var(--drt-staffing-faint); text-align: center; align-self: end; font-variant-numeric: tabular-nums; }
.drt-staffing__wd { display: grid; align-content: center; font-size: 12.5px; font-weight: 650; line-height: 1.2; text-align: left; border-radius: 8px; padding: 0 8px; }
