.drt-staffing__tip { --drt-staffing-tipbg: var(--drt-staffing-ink); --drt-staffing-tipink: var(--drt-staffing-bg); }

/* ---------------------------------------------------------------- container: rail */
@container drt-staffing (max-width: 960px) {
  .drt-staffing__app { grid-template-columns: 64px minmax(0, 1fr); }
  .drt-staffing__nav { padding: 16px 10px; align-items: center; }
