  .drt-staffing__actions { grid-column: 1 / -1; grid-template-columns: auto auto; justify-content: start; }
  .drt-staffing__weekp { height: 480px; }
}
/* ---------------------------------------------------------------- container: stacked */
@container drt-staffing (max-width: 760px) {
  .drt-staffing__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "nav" "top" "main"; }
