  .drt-staffing__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .drt-staffing__pgrid { grid-template-columns: 112px repeat(15, minmax(30px, 1fr)) 48px; }
  .drt-staffing__corner { padding-left: 10px; font-size: 10.5px; }
  .drt-staffing__row .who { padding-left: 10px; }
  .drt-staffing__row .hrs { padding-right: 8px; }
}
@container drt-staffing (max-width: 480px) {
  .drt-staffing__navbtn span, .drt-staffing__brandtx small { display: none; }
  .drt-staffing__navbtn { width: 40px; padding: 0; justify-content: center; }
  .drt-staffing__days { overflow-x: auto; max-width: 100%; scrollbar-width: none; }
  .drt-staffing__lvl .drt-staffing__kl { display: none; }
  .drt-staffing__ed { width: calc(100% - 24px); }
}

@media (prefers-reduced-motion: reduce) {
