const COLL = [
  ['Amara Osei', 'S', 14.2], ['Tom Lindqvist', 'S', 14.2], ['Priya Nair', 'T', 12.1], ['Callum Reid', 'T', 12.1], ['Sofia Marques', 'T', 12.1],
  ['Jonah Feld', 'T', 12.1], ['Ruth Ellery', 'T', 12.1], ['Hana Kobayashi', 'F', 12.1], ['Owen Pryce', 'F', 12.1], ['Leila Haddad', 'F', 12.1],
  ['Dev Mistry', 'F', 12.1], ['Marek Novak', 'B', 12.6], ['Grace Achebe', 'B', 12.6], ['Isla Moran', 'T', 12.1]
