svg.addEventListener('pointermove', e => {
  if (!G) return;
  const b = svg.getBoundingClientRect(), h = clamp(Math.floor((e.clientX - b.left) / G.bw), 0, N - 1);
  const xh = svg.querySelector('.xh'); xh.setAttribute('x', h * G.bw); xh.classList.add('is-on');
  const names = rota[day].map((x, i) => x && x.s <= H0 + h && H0 + h < x.e ? COLL[i].first : null).filter(Boolean);
  const gap = G.on[h] - G.rq[h];
  tip('<span class="drt-staffing__tt">' + DAYS[day][0] + ' · ' + hh(H0 + h) + '–' + hh(H0 + h + 1) + '</span>' +
    '<div class="drt-staffing__trow"><span>Forecast shoppers</span><b>' + FF[day][h] + '</b></div>' +
    '<div class="drt-staffing__trow"><span>Needed at ' + ratio + ' per colleague</span><b>' + G.rq[h] + '</b></div>' +
    '<div class="drt-staffing__trow"><span>On the floor</span><b>' + G.on[h] + (gap < 0 ? ' (' + gap + ')' : gap > 1 ? ' (+' + gap + ')' : '') + '</b></div>' +
    '<div style="margin-top:4px;opacity:.75;max-width:230px">' + (names.join(', ') || 'Nobody scheduled') + '</div>', e.clientX, e.clientY);
});
svg.addEventListener('pointerleave', () => { untip(); const xh = svg.querySelector('.xh'); if (xh) xh.classList.remove('is-on'); });

/* ================================================================ rota rows */
const rowsEl = $('.drt-staffing__rows');
const PLUS = '<svg class="drt-staffing__i" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';
rowsEl.innerHTML = COLL.map(c => '<div class="drt-staffing__row" role="listitem" data-c="' + c.i + '" style="--rc:' + ROLES[c.role][1] + '"><span class="who"><i></i><span><b>' + c.name + '</b><small>' + ROLES[c.role][0] + '</small></span></span><span class="slot"></span><span class="hrs"></span></div>').join('');
const rowOf = i => rowsEl.querySelector('[data-c="' + i + '"]');
const renderRow = (i, isNew) => {
  const row = rowOf(i), x = rota[day][i], c = COLL[i];
  const slot = row.querySelector('.slot');
  if (x) {
    let b = slot.querySelector('.drt-staffing__bar');
    if (!b) { slot.innerHTML = '<button type="button" class="drt-staffing__bar" aria-haspopup="dialog" aria-expanded="false"><span class="fill"></span><span class="lbl"></span></button>'; b = slot.querySelector('.drt-staffing__bar'); }
    b.style.setProperty('--a', x.s - H0 + 2); b.style.setProperty('--b', x.e - H0 + 2);
    b.querySelector('.lbl').textContent = hh(x.s) + '–' + hh(x.e);
    b.setAttribute('aria-label', c.name + ', ' + hh(x.s) + ' to ' + hh(x.e) + '. Edit shift');
    b.setAttribute('aria-expanded', String(edOpen === i));
    b.classList.toggle('is-new', !!isNew);
  } else {
    slot.innerHTML = '<button type="button" class="drt-staffing__add" aria-label="Add a shift for ' + c.name + '">' + PLUS + 'Off · add shift</button>';
  }
  row.querySelector('.hrs').textContent = x ? hrs(x) + ' h' : '–';
};
const renderRota = () => { COLL.forEach(c => renderRow(c.i)); };
/* FLIP one bar's fill from its old box to its new one; the label just follows */
const flipBar = (i, mutate) => {
  const b0 = rowOf(i).querySelector('.drt-staffing__bar .fill');
  const r0 = b0 && b0.getBoundingClientRect();
  mutate();
  const b1 = rowOf(i).querySelector('.drt-staffing__bar .fill');
  if (RM || !b1) return;
  if (!r0) { b1.parentElement.classList.add('is-new'); return; }
  const r1 = b1.getBoundingClientRect();
  if (!r1.width) return;
  b1.animate([{ transform: 'translateX(' + (r0.left - r1.left) + 'px) scaleX(' + (r0.width / r1.width) + ')' }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.3, 1.25, .45, 1)' });
};

/* ================================================================ KPIs */
const renderKpis = () => {
  const s = stats(day);
  roll($('[data-k="hrs"]'), s.sched, v => Math.round(v) + ' h');
  $('[data-s="hrs"]').textContent = 'budget ' + budget[day] + ' h · ' + (s.sched > budget[day] ? (s.sched - budget[day]) + ' h over' : (budget[day] - s.sched) + ' h spare');
  roll($('[data-k="cost"]'), s.cost, money);
  $('[data-s="cost"]').textContent = rota[day].filter(Boolean).length + ' colleagues · ' + money(s.cost / Math.max(1, sum(FF[day])) * 100) + ' per 100 shoppers';
  roll($('[data-k="under"]'), s.under, v => Math.round(v) + ' h');
  $('[data-s="under"]').textContent = s.peak.h > -1 ? 'worst ' + hh(H0 + s.peak.h) + ', ' + s.peak.gap + ' short' : 'every hour covered';
  roll($('[data-k="over"]'), s.over, v => Math.round(v) + ' h');
  $('[data-s="over"]').textContent = s.overH ? s.overH + ' hours with 2+ spare' : 'no slack beyond 1';
  const wk = sum(DAYS.map((_, d) => stats(d).sched)), wb = sum(budget);
  $('[data-out="wkhrs"]').textContent = wk + ' h';
  $('[data-out="wkbud"]').textContent = 'of ' + wb + ' h budget · ' + Math.round(wk / wb * 100) + '%';
  const bud = $('.drt-staffing__budget'); bud.style.setProperty('--p', Math.min(1, wk / wb).toFixed(3)); bud.classList.toggle('is-over', wk > wb);
  const rs = $('.drt-staffing__reset'), dy = dirty(day);
  rs.disabled = !dy; rs.title = dy ? 'Put ' + DAYS[day][1] + ' back to the published rota' : 'Nothing to undo: this day still matches the published rota';
  const fx = $('.drt-staffing__fix');
  if (fx.getAttribute('aria-busy') !== 'true') { fx.disabled = s.under === 0; fx.title = s.under === 0 ? 'No short-staffed hours on this day' : 'Extend or add shifts to cover ' + s.under + ' short hours'; }
  markGapDays();
};
const renderDay = () => { $('[data-out="dayname"]').textContent = DAYS[day][1]; renderChart(); renderRota(); renderKpis(); };

/* ================================================================ shift editor */
const ed = $('.drt-staffing__ed');
const placeEd = i => {
  const b = rowOf(i).querySelector('.drt-staffing__bar'); if (!b) return;
  const rr = root.getBoundingClientRect(), br = b.getBoundingClientRect();
  const w = ed.offsetWidth || 268, h = ed.offsetHeight || 190;
  let x = br.left - rr.left, y = br.bottom - rr.top + 8;
  if (y + h > rr.height - 8) y = br.top - rr.top - h - 8;
  x = clamp(x, 12, rr.width - w - 12); y = clamp(y, 12, rr.height - h - 12);
  ed.style.translate = x + 'px ' + y + 'px';
};
const fillEd = () => {
  const i = edOpen, x = rota[day][i], c = COLL[i];
  $('[data-out="edname"]', ed).textContent = c.name;
  ed.setAttribute('aria-label', 'Edit ' + c.name + '’s shift');
  $('[data-out="edrole"]', ed).textContent = ROLES[c.role][0] + ' · ' + DAYS[day][1] + ' · £' + c.rate.toFixed(2) + '/h';
  $('[data-out="edtime"]', ed).innerHTML = hh(x.s) + '–' + hh(x.e) + '<small>' + hrs(x) + ' h · ' + money(hrs(x) * c.rate) + '</small>';
  const dis = (k, off, why) => { const b = ed.querySelector('[data-ed="' + k + '"]'); b.disabled = off; b.title = off ? why : ''; };
  dis('s-1', x.s <= H0, 'The store opens at 07:00');
  dis('s+1', hrs(x) <= 3, 'Shifts are at least 3 hours');
  dis('e-1', hrs(x) <= 3, 'Shifts are at least 3 hours');
  dis('e+1', x.e >= H0 + N || hrs(x) >= 10, x.e >= H0 + N ? 'The store closes at 22:00' : 'Shifts are capped at 10 hours');
};
let edReturn = null;
const openEd = (i, focus) => {
  edOpen = i; edReturn = rowOf(i).querySelector('.drt-staffing__bar');
  $$('.drt-staffing__bar', rowsEl).forEach(b => b.setAttribute('aria-expanded', String(b === edReturn)));
  ed.hidden = false; fillEd(); placeEd(i);
  if (focus) (ed.querySelector('[data-ed]:not(:disabled)') || ed.querySelector('.drt-staffing__edx')).focus();
};
const closeEd = () => {
  if (edOpen < 0) return;
  edOpen = -1; ed.hidden = true;
  $$('.drt-staffing__bar', rowsEl).forEach(b => b.setAttribute('aria-expanded', 'false'));
  if (edReturn && edReturn.isConnected) edReturn.focus({ preventScroll: true });
};
const edit = (i, fn, msg) => {
  flipBar(i, () => { fn(rota[day][i]); renderRow(i); });
  renderChart(); renderKpis();
  if (msg) toast(msg);
};
ed.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || b.disabled) return;
  if (b.classList.contains('drt-staffing__edx')) { closeEd(); return; }
  const i = edOpen, k = b.dataset.ed, c = COLL[i];
  if (k === 'rm') {
    const x = rota[day][i];
    edOpen = -1; ed.hidden = true;
    rota[day][i] = null; renderRow(i); renderChart(); renderKpis();
    toast(c.first + '’s ' + hh(x.s) + '–' + hh(x.e) + ' shift removed');
    const add = rowOf(i).querySelector('.drt-staffing__add'); if (add) add.focus();
    return;
  }
  edit(i, x => { if (k === 's-1') x.s--; if (k === 's+1') x.s++; if (k === 'e-1') x.e--; if (k === 'e+1') x.e++; });
  fillEd(); placeEd(i);
});
ed.addEventListener('keydown', e => {
  if (e.key === 'Escape') { e.preventDefault(); closeEd(); return; }
  if (e.key === 'Tab') {
    const f = $$('button:not(:disabled)', ed); const a = f[0], z = f[f.length - 1];
    if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); } else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
  }
});
rowsEl.addEventListener('click', e => {
  const bar = e.target.closest('.drt-staffing__bar'), add = e.target.closest('.drt-staffing__add');
  const i = +(e.target.closest('.drt-staffing__row') || {}).dataset?.c;
  if (bar) { if (edOpen === i) closeEd(); else openEd(i, e.detail === 0); return; }
  if (add) {
    /* place a 4 h shift over the worst gap of the day */
    const rq = FF[day].map((_, h) => req(day, h) - onAt(day, h));
    let best = 0, bs = 0;
    for (let s = 0; s <= N - 4; s++) { const v = rq.slice(s, s + 4).reduce((a, g) => a + Math.max(0, g), 0); if (v > best) { best = v; bs = s; } }
    if (!best) bs = FF[day].indexOf(Math.max(...FF[day])) - 1;
    bs = clamp(bs, 0, N - 4);
    rota[day][i] = { s: H0 + bs, e: H0 + bs + 4 };
    renderRow(i, true); renderChart(); renderKpis();
    toast(COLL[i].first + ' added ' + hh(H0 + bs) + '–' + hh(H0 + bs + 4) + (best ? ', covering ' + best + ' short hour' + (best > 1 ? 's' : '') : ''));
    const nb = rowOf(i).querySelector('.drt-staffing__bar'); if (nb) nb.focus({ preventScroll: true });
  }
});
root.addEventListener('pointerdown', e => { if (edOpen > -1 && !ed.contains(e.target) && !e.target.closest('.drt-staffing__bar')) closeEd(); });
root.addEventListener('keydown', e => { if (e.key === 'Escape' && edOpen > -1) closeEd(); });

/* ================================================================ fill the gaps: extend neighbours first, then call in someone off */
$('.drt-staffing__fix').addEventListener('click', e => {
  const btn = e.currentTarget; if (btn.disabled || btn.getAttribute('aria-busy') === 'true') return;
  closeEd();
  btn.setAttribute('aria-busy', 'true'); btn.querySelector('span').textContent = 'Planning…';
  setTimeout(() => {
    if (!root.isConnected) return;
    const changed = new Set(), notes = [];
    for (let guard = 0; guard < 40; guard++) {
      const h = FF[day].findIndex((_, k) => onAt(day, k) < req(day, k));
      if (h < 0) break;
      const T = H0 + h;
      let k = rota[day].findIndex((x, i) => x && COLL[i].role !== 'S' && x.e === T && hrs(x) < 9);
      if (k > -1) { rota[day][k].e++; changed.add(k); continue; }
      k = rota[day].findIndex((x, i) => x && COLL[i].role !== 'S' && x.s === T + 1 && hrs(x) < 9);
      if (k > -1) { rota[day][k].s--; changed.add(k); continue; }
      k = rota[day].findIndex((x, i) => !x && COLL[i].role !== 'S');
      if (k > -1) { const s = Math.min(T, H0 + N - 4); rota[day][k] = { s, e: s + 4 }; changed.add(k); notes.push(COLL[k].first + ' called in'); continue; }
      break;
    }
    const before = new Map(); changed.forEach(i => { const f = rowOf(i).querySelector('.drt-staffing__bar .fill'); if (f) before.set(i, f.getBoundingClientRect()); });
    changed.forEach(i => renderRow(i, !before.has(i)));
    if (!RM) changed.forEach((i, n) => {
      const r0 = before.get(i), f = rowOf(i).querySelector('.drt-staffing__bar .fill'); if (!r0 || !f) return;
      const r1 = f.getBoundingClientRect();
      f.animate([{ transform: 'translateX(' + (r0.left - r1.left) + 'px) scaleX(' + (r0.width / r1.width) + ')' }, { transform: 'none' }], { duration: 560, delay: n * 70, easing: 'cubic-bezier(.3, 1.25, .45, 1)', fill: 'backwards' });
    });
    btn.removeAttribute('aria-busy'); btn.querySelector('span').textContent = 'Fill the gaps';
    renderChart(); renderKpis();
    const left = stats(day).under;
    toast(changed.size ? 'Adjusted ' + changed.size + ' shift' + (changed.size > 1 ? 's' : '') + (notes.length ? ' · ' + notes.join(', ') : '') + (left ? ' · ' + left + ' h still short' : ' · every hour covered') : 'No one free to cover the gap');
  }, RM ? 0 : 650);
});
$('.drt-staffing__reset').addEventListener('click', () => {
  closeEd();
  rota[day] = PUB[day].map(x => x && { s: x.s, e: x.e });
  COLL.forEach(c => flipBar(c.i, () => renderRow(c.i)));
  renderChart(); renderKpis();
  toast(DAYS[day][1] + ' reset to the published rota');
});

/* ================================================================ week coverage */
const wEl = $('.drt-staffing__wgrid');
const renderWeek = () => {
  let s = '<div class="drt-staffing__wh"></div>' + PROF.map((_, h) => '<div class="drt-staffing__wh">' + String(H0 + h).padStart(2, '0') + '</div>').join('') + '<div class="drt-staffing__wh">Hours · short</div>';
  DAYS.forEach((d, r) => {
    const st = stats(r);
    s += '<button type="button" class="drt-staffing__wd" data-day="' + r + '" aria-current="' + (r === day) + '">' + d[1].split(' ').slice(0, 2).join(' ') + '<small>' + money(st.cost) + '</small></button>';
    for (let h = 0; h < N; h++) {
      const g = onAt(r, h) - req(r, h), cl = g < 0 ? 'u' : g > 1 ? 'o' : 'z';
      const m = g < 0 ? Math.min(1, .3 + -g * .22) : g > 1 ? Math.min(.8, .18 + (g - 1) * .16) : .04;
      s += '<div role="gridcell" tabindex="' + (r === day && h === 0 ? 0 : -1) + '" class="drt-staffing__wc ' + cl + '" data-day="' + r + '" data-h="' + h + '" style="--m:' + m + ';--r:' + r + ';--h:' + h + '" aria-label="' + d[1] + ' ' + hh(H0 + h) + ': ' + (g < 0 ? -g + ' short' : g > 0 ? g + ' spare' : 'exactly covered') + '">' + (g < 0 ? '−' + -g : g > 1 ? '+' + g : '') + '</div>';
    }
    s += '<div class="drt-staffing__wt">' + st.sched + ' h<small>' + (st.under ? st.under + ' h short' : 'covered') + '</small></div>';
  });
  wEl.innerHTML = s;
};
wEl.addEventListener('click', e => {
  const t = e.target.closest('[data-day]'); if (!t) return;
  const d = +t.dataset.day;
  setDay(String(d));
  go('day');
  toast('Opened ' + DAYS[d][1] + (t.dataset.h ? ' at ' + hh(H0 + +t.dataset.h) : ''));
});
wEl.addEventListener('keydown', e => {
  const c = e.target.closest('.drt-staffing__wc'); if (!c) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); c.click(); return; }
  let r = +c.dataset.day, h = +c.dataset.h;
  if (e.key === 'ArrowRight') h = Math.min(N - 1, h + 1); else if (e.key === 'ArrowLeft') h = Math.max(0, h - 1);
  else if (e.key === 'ArrowDown') r = Math.min(6, r + 1); else if (e.key === 'ArrowUp') r = Math.max(0, r - 1); else return;
  e.preventDefault();
  const n = wEl.querySelector('.drt-staffing__wc[data-day="' + r + '"][data-h="' + h + '"]');
  c.tabIndex = -1; n.tabIndex = 0; n.focus(); tipAt(esc(n.getAttribute('aria-label')), n);
});
wEl.addEventListener('focusout', untip);
wEl.addEventListener('pointermove', e => {
  const c = e.target.closest('.drt-staffing__wc'); if (!c) { untip(); return; }
  const r = +c.dataset.day, h = +c.dataset.h;
  tip('<span class="drt-staffing__tt">' + DAYS[r][1] + ' · ' + hh(H0 + h) + '</span><div class="drt-staffing__trow"><span>Shoppers</span><b>' + FF[r][h] + '</b></div><div class="drt-staffing__trow"><span>Needed</span><b>' + req(r, h) + '</b></div><div class="drt-staffing__trow"><span>On the floor</span><b>' + onAt(r, h) + '</b></div><div style="opacity:.7;margin-top:3px">Click to open the day</div>', e.clientX, e.clientY);
});
wEl.addEventListener('pointerleave', untip);

/* ================================================================ wiring */
const go = navInit(v => { closeEd(); if (v === 'week') renderWeek(); else renderChart(); });
const setDay = radios(daysEl, v => { closeEd(); day = +v; renderDay(); });
radios($('.drt-staffing__lvl'), v => { ratio = +v; renderChart(); renderKpis(); if (!$('[data-view="week"]').hidden) renderWeek(); toast('Planning at ' + ratio + ' shoppers per colleague'); });
renderDay();
onResize(chartBox, () => { renderChart(); if (edOpen > -1) placeEd(edOpen); });

css:
.drt-floor {
  width: 100%;
  height: var(--drt-floor-h, 680px);
  container-type: inline-size;
  container-name: drt-floor;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-floor-bg);
  color: var(--drt-floor-ink);
  font: 13px/1.45 var(--drt-floor-sans);
  accent-color: var(--drt-floor-accent);
  -webkit-font-smoothing: antialiased;
  --drt-floor-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-floor-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-floor-out: cubic-bezier(.22, 1, .36, 1);
  --drt-floor-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-floor-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-floor-focus, var(--drt-floor-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-floor__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-floor__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-floor__num, & .drt-floor__tab { font-variant-numeric: tabular-nums; }
}
.drt-floor__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-floor-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-floor-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-floor__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-floor-tipbg, color-mix(in oklch, var(--drt-floor-ink) 94%, var(--drt-floor-bg)));
  color: var(--drt-floor-tipink, var(--drt-floor-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-floor-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-floor__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-floor__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-floor__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-floor__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-floor-tipbg, color-mix(in oklch, var(--drt-floor-ink) 94%, var(--drt-floor-bg)));
  color: var(--drt-floor-tipink, var(--drt-floor-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-floor-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

.drt-floor {
  /* re-theme with these four (plus the heat ramp below) */
  --drt-floor-bg: oklch(0.195 0.006 250);
  --drt-floor-ink: oklch(0.94 0.008 250);
  --drt-floor-accent: oklch(0.86 0.15 95);
  --drt-floor-plan: oklch(0.72 0.02 250);
  /* heat ramp: cold to hot, read by the canvas */
  --drt-floor-heat1: oklch(0.42 0.08 205);
  --drt-floor-heat2: oklch(0.68 0.14 160);
  --drt-floor-heat3: oklch(0.84 0.16 95);
  --drt-floor-heat4: oklch(0.66 0.21 35);
  /* derived */
  --drt-floor-card: color-mix(in oklch, var(--drt-floor-bg), var(--drt-floor-ink) 4%);
  --drt-floor-side: color-mix(in oklch, var(--drt-floor-bg), black 22%);
  --drt-floor-line: color-mix(in oklch, var(--drt-floor-ink) 11%, transparent);
  --drt-floor-hair: color-mix(in oklch, var(--drt-floor-ink) 6%, transparent);
  --drt-floor-mute: color-mix(in oklch, var(--drt-floor-ink) 64%, var(--drt-floor-bg));
  --drt-floor-faint: color-mix(in oklch, var(--drt-floor-ink) 42%, var(--drt-floor-bg));
  color-scheme: dark;
  border-radius: 14px;
}
.drt-floor__app { height: 100%; display: grid; grid-template-columns: 180px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }

/* ---------------------------------------------------------------- nav */
.drt-floor__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--drt-floor-side); border-radius: 14px 0 0 14px; }
.drt-floor__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .drt-floor__logo { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: var(--drt-floor-accent); color: var(--drt-floor-bg); flex: none; }
  & :where(.drt-floor__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 15px; font-weight: 760; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--drt-floor-faint); }
}
.drt-floor__navlist { display: grid; gap: 2px; }
.drt-floor__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px; color: var(--drt-floor-mute); font-weight: 560; text-align: left; transition: background-color .15s, color .15s;
  &:hover { background: color-mix(in oklch, var(--drt-floor-ink) 6%, transparent); color: var(--drt-floor-ink); }
  &[aria-current="page"] { background: color-mix(in oklch, var(--drt-floor-ink) 9%, transparent); color: var(--drt-floor-ink); }
  &[aria-current="page"]::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--drt-floor-accent); }
}
.drt-floor__kl { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--drt-floor-faint); }
.drt-floor__scale {
  display: grid; gap: 6px; padding: 0 6px;
  & .drt-floor__ramp { height: 10px; border-radius: 5px; background: linear-gradient(90deg, color-mix(in oklch, var(--drt-floor-heat1) 30%, transparent), var(--drt-floor-heat1) 18%, var(--drt-floor-heat2) 42%, var(--drt-floor-heat3) 68%, var(--drt-floor-heat4) 90%, oklch(0.97 0.04 90)); }
  & .drt-floor__rampx { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--drt-floor-faint); }
}
.drt-floor__navfoot {
  margin-top: auto; display: grid; gap: 3px; padding: 12px 8px 2px; border-top: 1px solid var(--drt-floor-line);
  & b { font-weight: 620; }
  & small { font-size: 11px; color: var(--drt-floor-faint); }
}

/* ---------------------------------------------------------------- top */
.drt-floor__top { grid-area: top; display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; padding: 16px 20px 12px; }
.drt-floor__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-floor-faint); font-variant-numeric: tabular-nums; }
.drt-floor__title h2 { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; margin-top: 3px; }
.drt-floor__ctrls { display: flex; gap: 10px; flex-wrap: wrap; }
.drt-floor__seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--drt-floor-ink) 6%, transparent);
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 580; color: var(--drt-floor-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--drt-floor-ink); }
  & button[aria-checked="true"] { background: var(--drt-floor-accent); color: var(--drt-floor-bg); }
}

/* ---------------------------------------------------------------- main */
.drt-floor__main { grid-area: main; min-height: 0; padding: 0 20px 18px; overflow: hidden; }
.drt-floor__view { height: 100%; }
.drt-floor__mv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 288px; }
.drt-floor__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-floor-card); overflow: hidden; }
.drt-floor__mapp { padding: 12px 12px 10px; gap: 10px; }
.drt-floor__mapwrap { flex: 1; min-height: 0; display: grid; place-items: center; }
.drt-floor__map { position: relative; width: 100%; aspect-ratio: 40 / 24; border-radius: 6px; background: color-mix(in oklch, var(--drt-floor-bg), black 18%); }
.drt-floor__cv { position: absolute; inset: 0; width: 100%; height: 100%; border-radius: inherit; }
.drt-floor__plan {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .wall { fill: none; stroke: var(--drt-floor-plan); stroke-width: .28; stroke-linecap: round; }
  & .door { stroke: var(--drt-floor-accent); stroke-width: .32; stroke-dasharray: .5 .4; }
  & .fx { fill: none; stroke: color-mix(in oklch, var(--drt-floor-plan) 40%, transparent); stroke-width: .07; }
  & .drt-floor__zone { cursor: pointer; outline: none; }
  & .drt-floor__zone .zr { fill: transparent; stroke: color-mix(in oklch, var(--drt-floor-plan) 55%, transparent); stroke-width: .09; stroke-dasharray: .35 .25; transition: stroke .2s, fill .2s, stroke-width .2s; }
  & .drt-floor__zone:hover .zr { fill: color-mix(in oklch, var(--drt-floor-ink) 7%, transparent); stroke: var(--drt-floor-ink); stroke-dasharray: none; }
  & .drt-floor__zone:focus-visible .zr { stroke: var(--drt-floor-accent); stroke-width: .2; stroke-dasharray: none; }
  & .drt-floor__zone[aria-pressed="true"] .zr { stroke: var(--drt-floor-accent); stroke-width: .18; stroke-dasharray: none; fill: color-mix(in oklch, var(--drt-floor-accent) 8%, transparent); }
  & .zl { font-size: .74px; font-weight: 650; fill: var(--drt-floor-ink); paint-order: stroke; stroke: color-mix(in oklch, var(--drt-floor-bg) 80%, transparent); stroke-width: .22px; letter-spacing: .01em; pointer-events: none; }
  & .zv { font-size: .62px; font-weight: 600; fill: var(--drt-floor-ink); opacity: .78; paint-order: stroke; stroke: color-mix(in oklch, var(--drt-floor-bg) 80%, transparent); stroke-width: .2px; pointer-events: none; font-variant-numeric: tabular-nums; }
  & .drt-floor__zone[aria-pressed="true"] .zl { fill: var(--drt-floor-accent); }
  &.is-enter .zr { animation: drt-floor-trace 1s var(--drt-floor-out) calc(var(--i) * 50ms) backwards; }
  &.is-enter .zl, &.is-enter .zv { animation: drt-floor-in .6s var(--drt-floor-out) calc(300ms + var(--i) * 50ms) backwards; }
}
@keyframes drt-floor-trace { from { opacity: 0; } }
@keyframes drt-floor-in { from { opacity: 0; translate: 0 .4px; } }

/* timeline */
.drt-floor__time { display: grid; grid-template-columns: auto minmax(0, 1fr) 56px; gap: 14px; align-items: center; }
.drt-floor__play {
  height: 34px; display: flex; align-items: center; gap: 7px; padding: 0 13px 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 640; background: var(--drt-floor-ink); color: var(--drt-floor-bg); white-space: nowrap; transition: filter .15s;
  & .drt-floor__i { width: 16px; height: 16px; }
  & .p { fill: currentColor; stroke: none; }
  & .s { display: none; stroke-width: 2.6; }
  &[aria-pressed="true"] .p { display: none; }
  &[aria-pressed="true"] .s { display: block; }
  &:hover { filter: brightness(.92); }
}
.drt-floor__scrub { position: relative; height: 44px; }
.drt-floor__area { position: absolute; left: 8px; right: 8px; top: 2px; height: 26px; width: calc(100% - 16px); }
.drt-floor__area path { fill: color-mix(in oklch, var(--drt-floor-ink) 12%, transparent); stroke: color-mix(in oklch, var(--drt-floor-ink) 30%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; transition: d .6s var(--drt-floor-out); }
.drt-floor__range {
  position: absolute; left: 0; right: 0; top: 18px; width: 100%; margin: 0; height: 22px; background: transparent; appearance: none; -webkit-appearance: none; cursor: grab;
  &::-webkit-slider-runnable-track { height: 3px; border-radius: 2px; background: color-mix(in oklch, var(--drt-floor-ink) 18%, transparent); }
  &::-moz-range-track { height: 3px; border-radius: 2px; background: color-mix(in oklch, var(--drt-floor-ink) 18%, transparent); }
  &::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; margin-top: -6.5px; border-radius: 50%; background: var(--drt-floor-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--drt-floor-accent) 25%, transparent); transition: scale .2s var(--drt-floor-snap); }
  &::-moz-range-thumb { width: 16px; height: 16px; border: 0; border-radius: 50%; background: var(--drt-floor-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--drt-floor-accent) 25%, transparent); }
  &:active { cursor: grabbing; }
  &:active::-webkit-slider-thumb { scale: 1.2; }
}
.drt-floor__ticks { position: absolute; left: 8px; right: 8px; bottom: -6px; display: flex; justify-content: space-between; font-size: 10px; color: var(--drt-floor-faint); font-variant-numeric: tabular-nums; pointer-events: none; }
.drt-floor__ticks span { width: 0; display: flex; justify-content: center; }
.drt-floor__clock { font: 700 18px/1 var(--drt-floor-mono); letter-spacing: -.02em; color: var(--drt-floor-accent); text-align: right; font-variant-numeric: tabular-nums; }

/* side */
.drt-floor__side { padding: 14px 0 0; }
.drt-floor__zd {
  padding: 0 16px 12px; display: grid; gap: 4px; border-bottom: 1px solid var(--drt-floor-line);
  & h3 { font-size: 17px; font-weight: 720; letter-spacing: -.02em; }
  & .drt-floor__zsub { font-size: 11.5px; color: var(--drt-floor-faint); }
  & .drt-floor__zday { font-size: 11.5px; color: var(--drt-floor-mute); font-variant-numeric: tabular-nums; }
  & .drt-floor__zday b { color: var(--drt-floor-ink); font-weight: 650; }
}
.drt-floor__zstats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; margin: 8px 0 4px;
  & div { display: grid; }
  & dt { font-size: 10px; text-transform: uppercase; letter-spacing: .07em; color: var(--drt-floor-faint); font-weight: 600; }
  & dd { font-size: 16px; font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
}
.drt-floor__zspark { width: 100%; height: 54px; }
.drt-floor__zspark .a { fill: color-mix(in oklch, var(--drt-floor-accent) 16%, transparent); }
.drt-floor__zspark .l { fill: none; stroke: var(--drt-floor-accent); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.drt-floor__zspark .m { stroke: var(--drt-floor-ink); stroke-width: 1; vector-effect: non-scaling-stroke; stroke-dasharray: 2 2; }
.drt-floor__rankh { display: flex; justify-content: space-between; padding: 12px 16px 6px; }
.drt-floor__rank { flex: 1; min-height: 0; padding: 0 8px 10px; display: grid; align-content: start; gap: 2px; }
.drt-floor__rank button {
  width: 100%; display: grid; grid-template-columns: 16px minmax(0, 1fr) 46px 44px; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 8px; text-align: left; font-size: 12.5px; transition: background-color .15s;
  & .n { font-size: 11px; color: var(--drt-floor-faint); font-variant-numeric: tabular-nums; }
  & .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bar { height: 6px; border-radius: 3px; background: color-mix(in oklch, var(--drt-floor-ink) 8%, transparent); overflow: hidden; }
  & .bar i { display: block; height: 100%; background: var(--c); transform-origin: 0 50%; scale: var(--w) 1; transition: scale .5s var(--drt-floor-out); }
  & .v { text-align: right; font-size: 12px; font-weight: 640; font-variant-numeric: tabular-nums; }
  &:hover { background: color-mix(in oklch, var(--drt-floor-ink) 6%, transparent); }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--drt-floor-accent) 13%, transparent); }
  &[aria-pressed="true"] .nm { color: var(--drt-floor-accent); font-weight: 650; }
}

/* ---------------------------------------------------------------- table view */
.drt-floor__tv { display: flex; flex-direction: column; }
.drt-floor__tablep { flex: 1; }
.drt-floor__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding: 12px 16px 8px;
  & h3 { font-size: 13px; font-weight: 650; }
  & h3 small { font-weight: 500; color: var(--drt-floor-faint); margin-left: 6px; font-size: 11.5px; }
}
.drt-floor__hint { font-size: 11px; color: var(--drt-floor-faint); }
.drt-floor__tw { flex: 1; min-height: 0; padding: 0 8px 8px; }
.drt-floor__table {
  min-width: 640px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--drt-floor-card); text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-floor-faint); padding: 8px 10px; border-bottom: 1px solid var(--drt-floor-line); }
