  & th[aria-sort="ascending"] button::after { content: "↑"; }
  & th[aria-sort="descending"] button::after { content: "↓"; }
  & .n { text-align: right; }
  & th.n button { flex-direction: row-reverse; }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--drt-floor-hair); }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: color-mix(in oklch, var(--drt-floor-ink) 5%, transparent); }
  & tbody tr:focus-visible { outline-offset: -2px; }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--drt-floor-accent) 11%, transparent); }
  & td:first-child { font-weight: 620; }
  & td .sw { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 8px; background: var(--c); }
  & tfoot td { font-weight: 700; border-bottom: 0; border-top: 1px solid var(--drt-floor-line); color: var(--drt-floor-ink); }
}

/* ---------------------------------------------------------------- container: rail */
@container drt-floor (max-width: 960px) {
  .drt-floor__app { grid-template-columns: 64px minmax(0, 1fr); }
  .drt-floor__nav { padding: 16px 10px; align-items: center; }
  .drt-floor__brandtx, .drt-floor__navbtn span, .drt-floor__navfoot, .drt-floor__scale .drt-floor__kl, .drt-floor__scale .drt-floor__rampx { display: none; }
  .drt-floor__scale { padding: 0; }
