  .drt-floor__brand { padding: 0; }
  .drt-floor__navbtn { width: 44px; justify-content: center; padding: 0; }
  .drt-floor__navbtn[aria-current="page"]::before { left: -10px; }
  .drt-floor__main { overflow: auto; scrollbar-width: thin; }
  .drt-floor__view { height: auto; }
  .drt-floor__mv { grid-template-columns: minmax(0, 1fr); }
  .drt-floor__side { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto 1fr; padding: 14px 0 6px; }
  .drt-floor__zd { grid-row: 1 / 3; border-bottom: 0; border-right: 1px solid var(--drt-floor-line); }
  .drt-floor__rank { max-height: 260px; }
  .drt-floor__tablep { height: 480px; }
}
/* ---------------------------------------------------------------- container: stacked */
@container drt-floor (max-width: 760px) {
  .drt-floor__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "nav" "top" "main"; }
  .drt-floor__nav { flex-direction: row; align-items: center; padding: 10px 14px; gap: 10px; border-radius: 14px 14px 0 0; }
  .drt-floor__brandtx { display: grid; }
  .drt-floor__navlist { display: flex; gap: 4px; margin-left: auto; }
  .drt-floor__navbtn { width: auto; padding: 0 10px; }
  .drt-floor__navbtn span { display: inline; }
  .drt-floor__navbtn[aria-current="page"]::before { left: 10px; right: 10px; top: auto; bottom: -11px; width: auto; height: 3px; border-radius: 3px 3px 0 0; }
  .drt-floor__scale { display: none; }
  .drt-floor__top { padding: 12px 14px 10px; }
  .drt-floor__main { padding: 0 14px 14px; }
  .drt-floor__side { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; }
  .drt-floor__zd { grid-row: auto; border-right: 0; border-bottom: 1px solid var(--drt-floor-line); }
}
@container drt-floor (max-width: 480px) {
  .drt-floor__navbtn span, .drt-floor__brandtx small { display: none; }
  .drt-floor__navbtn { width: 40px; padding: 0; justify-content: center; }
  .drt-floor__seg button { padding: 0 9px; font-size: 12px; }
  .drt-floor__time { grid-template-columns: auto minmax(0, 1fr); }
  .drt-floor__clock { grid-column: 1 / -1; grid-row: 1; text-align: left; }
  .drt-floor__play span { display: none; }
  .drt-floor__plan .zv { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .drt-floor {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-delay: 0s !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
  }
}

