/* single choice group of role=radio buttons: arrows move, click / Enter / Space choose */
const radios = (group, onChange) => {
  const items = $$('[role=radio]', group);
  const set = (b, focus, silent) => {
    items.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
    if (focus) b.focus();
    if (!silent) onChange(b.dataset.v, b);
  };
  items.forEach(x => { x.tabIndex = x.getAttribute('aria-checked') === 'true' ? 0 : -1; });
  group.addEventListener('click', e => {
    const b = e.target.closest('[role=radio]');
    if (b && group.contains(b) && b.getAttribute('aria-checked') !== 'true') set(b);
  });
  group.addEventListener('keydown', e => {
    const i = items.indexOf(e.target.closest('[role=radio]'));
    if (i < 0) return;
    const k = e.key;
    const j = k === 'ArrowRight' || k === 'ArrowDown' ? (i + 1) % items.length : k === 'ArrowLeft' || k === 'ArrowUp' ? (i - 1 + items.length) % items.length : k === 'Home' ? 0 : k === 'End' ? items.length - 1 : -1;
    if (j > -1) { e.preventDefault(); set(items[j], true); }
  });
  return (v, silent) => { const b = items.find(x => x.dataset.v === v); if (b) set(b, false, silent); };
};
/* FLIP: measure, mutate, play the difference back with the Web Animations API */
const flip = (els, mutate, opts = {}) => {
  const first = new Map(els.filter(e => e.isConnected).map(e => [e, e.getBoundingClientRect()]));
  mutate();
  if (RM) return;
  first.forEach((f, e) => {
    if (!e.isConnected) return;
    const l = e.getBoundingClientRect(), dx = f.left - l.left, dy = f.top - l.top;
    if (Math.abs(dx) > .5 || Math.abs(dy) > .5) e.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: opts.duration || 560, easing: opts.easing || EASE, delay: opts.delay ? opts.delay(e) : 0, fill: 'backwards' });
  });
};
/* views: nav buttons carry data-go, views carry data-view; arrows move along the nav */
const navInit = onSwitch => {
  const btns = $$('[data-go]');
  const go = (v, focus) => {
    btns.forEach(b => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
    $$('[data-view]').forEach(p => { p.hidden = p.dataset.view !== v; });
    untip();
    const b = btns.find(x => x.dataset.go === v);
    if (focus && b) b.focus();
    if (onSwitch) onSwitch(v);
  };
  btns.forEach(b => b.addEventListener('click', () => { if (!b.hasAttribute('aria-current')) go(b.dataset.go); }));
  const list = btns[0] && btns[0].closest('ul, ol');
  if (list) list.addEventListener('keydown', e => {
    const i = btns.indexOf(e.target.closest('[data-go]'));
    if (i < 0) return;
    const d = e.key === 'ArrowDown' || e.key === 'ArrowRight' ? 1 : e.key === 'ArrowUp' || e.key === 'ArrowLeft' ? -1 : 0;
    if (d) { e.preventDefault(); btns[(i + d + btns.length) % btns.length].focus(); }
