};
/* a chart remembers the size it was drawn at; a ResizeObserver redraws only on a real change */
const measure = el => { const W = el.clientWidth, H = el.clientHeight; el._rw = W; el._rh = H; return [W, H]; };
const onResize = (el, fn) => {
  let raf = 0;
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (el.clientWidth === el._rw && el.clientHeight === el._rh) return;
    cancelAnimationFrame(raf);
