/* ================================================================ heat field: gaussian kernels into a low-res grid, LUT colourised */
const GW = 160, GH = 96, SC = GW / 40;
const field = new Float32Array(GW * GH);
const low = document.createElement('canvas'); low.width = GW; low.height = GH;
const lctx = low.getContext('2d');
const img = lctx.createImageData(GW, GH);
let LUT = null;
const buildLUT = () => {
  const c = document.createElement('canvas'); c.width = 256; c.height = 1;
  const g = c.getContext('2d'), cs = getComputedStyle(root);
  const v = n => cs.getPropertyValue('--drt-floor-heat' + n).trim();
  try {
    const gr = g.createLinearGradient(0, 0, 256, 0);
    gr.addColorStop(0, v(1)); gr.addColorStop(.38, v(2)); gr.addColorStop(.66, v(3)); gr.addColorStop(.9, v(4)); gr.addColorStop(1, 'rgb(255, 244, 214)');
    g.fillStyle = gr; g.fillRect(0, 0, 256, 1);
  } catch (e) {
    const gr = g.createLinearGradient(0, 0, 256, 0);
    [[0, '#1d5f6e'], [.38, '#3fae86'], [.66, '#e6cf55'], [.9, '#e2603a'], [1, '#fff4d6']].forEach(([o, col]) => gr.addColorStop(o, col));
    g.fillStyle = gr; g.fillRect(0, 0, 256, 1);
