    const a = i < 8 ? 0 : Math.min(1, Math.pow(i / 255, .55) * 1.25);
    LUT[i * 4] = d[i * 4]; LUT[i * 4 + 1] = d[i * 4 + 1]; LUT[i * 4 + 2] = d[i * 4 + 2]; LUT[i * 4 + 3] = Math.round(a * 235);
  }
};
const KR = 9, KER = new Float32Array((KR * 2 + 1) ** 2);
for (let j = -KR; j <= KR; j++) for (let i = -KR; i <= KR; i++) KER[(j + KR) * (KR * 2 + 1) + i + KR] = Math.exp(-(i * i + j * j) / (2 * 3.6 * 3.6));
let gain = 1;
const computeField = () => {
  field.fill(0);
  const mx = maxFor(day, metric);
  ZONES.forEach((z, zi) => {
    const v = mval(day, zi, t) / mx;
    PTS[zi].forEach(p => {
      const cx = Math.round(p.x * SC), cy = Math.round(p.y * SC), wv = v * p.w;
      for (let j = -KR; j <= KR; j++) {
