const tick = now => {
  if (!root.isConnected) return;
  raf = 0;
  if (!playing || !onScreen || document.hidden) return;
  const dt = Math.min(64, now - (last || now)); last = now;
  t = Math.min(18, t + dt / 900);
  update();
  if (t >= 18) { stop(); toast('Day replayed · ' + DAYS[day].n); return; }
  raf = requestAnimationFrame(tick);
};
const kick = () => { if (!raf && playing) { last = 0; raf = requestAnimationFrame(tick); } };
const start = () => { if (t >= 17.9) t = 9; playing = true; playBtn.setAttribute('aria-pressed', 'true'); playBtn.querySelector('span').textContent = 'Pause'; kick(); };
const stop = () => { playing = false; playBtn.setAttribute('aria-pressed', 'false'); playBtn.querySelector('span').textContent = t >= 17.9 ? 'Replay day' : 'Play day'; if (raf) cancelAnimationFrame(raf); raf = 0; renderRank(true); };
playBtn.addEventListener('click', () => { if (playing) stop(); else start(); });
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); return; } onScreen = es[es.length - 1].isIntersecting; if (onScreen) kick(); });
io.observe(root);
const onVis = () => { if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; } if (!document.hidden) kick(); };
document.addEventListener('visibilitychange', onVis);

/* ================================================================ table */
const tbody = $('.drt-floor__table tbody');
let tsort = 'visits', tdir = -1;
const dayRows = () => ZONES.map((z, zi) => {
  const r = M[day][zi].reduce((a, x) => ({ visits: a.visits + x.visits, dw: a.dw + x.dwell * x.visits, sales: a.sales + x.sales }), { visits: 0, dw: 0, sales: 0 });
  return { z, zi, name: z.n, area: z.area, visits: r.visits, dwell: r.dw / r.visits, sales: r.sales, spm: r.sales / z.area, conv: z.conv ? r.sales / (z.aov || 1) / r.visits : 0 };
});
const renderTable = () => {
  const rows = dayRows().sort((a, b) => tsort === 'name' ? tdir * a.name.localeCompare(b.name) : tdir * (a[tsort] - b[tsort]));
  const mx = maxFor(day, 'visits');
  tbody.innerHTML = rows.map(r => '<tr tabindex="-1" data-k="' + r.z.k + '" aria-selected="' + (r.z.k === sel) + '"><td><span class="sw" style="--c:color-mix(in oklch, var(--drt-floor-heat2), var(--drt-floor-heat4) ' + Math.round(clamp(r.visits / r.area / (mx * HRS * .7), 0, 1) * 100) + '%)"></span>' + r.name + '</td><td class="n">' + r.area.toFixed(0) + ' m²</td><td class="n">' + r.visits.toLocaleString('en-GB') + '</td><td class="n">' + r.dwell.toFixed(1) + ' min</td><td class="n">' + (r.z.conv ? money(r.sales) : '–') + '</td><td class="n">' + (r.z.conv ? '£' + Math.round(r.spm).toLocaleString('en-GB') : '–') + '</td><td class="n">' + (r.z.conv ? (r.conv * 100).toFixed(1) + '%' : '–') + '</td></tr>').join('');
  const all = dayRows(), ts = sum(all.map(r => r.sales)), tv = sum(all.map(r => r.visits)), ta = sum(all.map(r => r.area));
  $('.drt-floor__table tfoot').innerHTML = '<tr><td>All zones</td><td class="n">' + ta.toFixed(0) + ' m²</td><td class="n">' + tv.toLocaleString('en-GB') + '</td><td class="n"></td><td class="n">' + money(ts) + '</td><td class="n">£' + (ts / ta).toFixed(0) + '</td><td class="n"></td></tr>';
  const first = tbody.querySelector('[aria-selected="true"]') || tbody.firstElementChild; if (first) first.tabIndex = 0;
};
$$('.drt-floor__table th button').forEach(b => b.addEventListener('click', () => {
  const k = b.dataset.sort;
  if (tsort === k) tdir = -tdir; else { tsort = k; tdir = k === 'name' ? 1 : -1; }
  $$('.drt-floor__table th').forEach(th => { const bb = th.querySelector('button'); th.setAttribute('aria-sort', bb.dataset.sort === tsort ? (tdir > 0 ? 'ascending' : 'descending') : 'none'); });
  renderTable();
}));
const openRow = tr => { select(tr.dataset.k); go('map'); toast(ZONES.find(z => z.k === tr.dataset.k).n + ' highlighted on the map'); };
tbody.addEventListener('click', e => { const tr = e.target.closest('tr'); if (tr) openRow(tr); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr'); if (!tr) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openRow(tr); return; }
  const n = e.key === 'ArrowDown' ? tr.nextElementSibling : e.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (n) { e.preventDefault(); tr.tabIndex = -1; n.tabIndex = 0; n.focus(); }
});

/* ================================================================ wiring */
const go = navInit(v => { if (v === 'table') { if (playing) stop(); renderTable(); } else { requestAnimationFrame(() => { if (!root.isConnected) return; sizeMap(); update(true); }); } });
radios($$('.drt-floor__seg')[0], v => {
  metric = v; $('[data-out="scalename"]').textContent = METRIC[v].name; $('[data-out="rankby"]').textContent = METRIC[v].rank;
  update(true);
});
radios($$('.drt-floor__seg')[1], v => {
  day = +v; $('[data-out="dayname"]').textContent = DAYS[day].n; $('[data-out="tday"]').textContent = DAYS[day].n;
  renderArea(); update(true); if (!$('[data-view="table"]').hidden) renderTable();
});
buildPlan(); renderArea();
$('[data-out="zoned"]').textContent = ZONES.length + ' zones cover ' + Math.round(sum(ZONES.map(z => z.area))) + ' m² · 36 ceiling sensors';
const bloom = () => {
  if (RM) { gain = 1; sizeMap(); update(true); return; }
  const t0 = performance.now();
  gain = 0; sizeMap(); update(true);
  const step = now => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / 1100);
    gain = 1 - Math.pow(1 - k, 3); paint();
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
};
bloom();
onResize($('.drt-floor__mapwrap'), sizeMap);

css:
.drt-shrink {
  width: 100%;
  height: var(--drt-shrink-h, 680px);
  container-type: inline-size;
  container-name: drt-shrink;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-shrink-bg);
  color: var(--drt-shrink-ink);
  font: 13px/1.45 var(--drt-shrink-sans);
  accent-color: var(--drt-shrink-accent);
  -webkit-font-smoothing: antialiased;
  --drt-shrink-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-shrink-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-shrink-out: cubic-bezier(.22, 1, .36, 1);
  --drt-shrink-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-shrink-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-shrink-focus, var(--drt-shrink-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-shrink__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-shrink__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-shrink__num, & .drt-shrink__tab { font-variant-numeric: tabular-nums; }
}
.drt-shrink__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-shrink-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-shrink-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-shrink__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-shrink-tipbg, color-mix(in oklch, var(--drt-shrink-ink) 94%, var(--drt-shrink-bg)));
  color: var(--drt-shrink-tipink, var(--drt-shrink-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-shrink-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-shrink__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-shrink__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-shrink__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-shrink__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-shrink-tipbg, color-mix(in oklch, var(--drt-shrink-ink) 94%, var(--drt-shrink-bg)));
  color: var(--drt-shrink-tipink, var(--drt-shrink-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-shrink-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

.drt-shrink {
  /* re-theme with these four */
  --drt-shrink-bg: oklch(0.972 0.01 88);
  --drt-shrink-ink: oklch(0.26 0.03 262);
  --drt-shrink-accent: oklch(0.47 0.14 24);
  --drt-shrink-good: oklch(0.55 0.09 160);
  /* derived */
  --drt-shrink-card: color-mix(in oklch, var(--drt-shrink-bg), white 65%);
  --drt-shrink-side: color-mix(in oklch, var(--drt-shrink-bg), var(--drt-shrink-ink) 4.5%);
  --drt-shrink-line: color-mix(in oklch, var(--drt-shrink-ink) 14%, transparent);
  --drt-shrink-hair: color-mix(in oklch, var(--drt-shrink-ink) 7%, transparent);
  --drt-shrink-mute: color-mix(in oklch, var(--drt-shrink-ink) 66%, var(--drt-shrink-bg));
  --drt-shrink-faint: color-mix(in oklch, var(--drt-shrink-ink) 45%, var(--drt-shrink-bg));
  --drt-shrink-slate: color-mix(in oklch, var(--drt-shrink-ink) 62%, var(--drt-shrink-bg));
  --drt-shrink-t-damage: color-mix(in oklch, var(--drt-shrink-accent), oklch(0.75 0.13 60) 55%);
  --drt-shrink-t-theft: var(--drt-shrink-accent);
  --drt-shrink-t-admin: color-mix(in oklch, var(--drt-shrink-accent), var(--drt-shrink-ink) 45%);
  --drt-shrink-t-supplier: color-mix(in oklch, var(--drt-shrink-accent), oklch(0.7 0.1 320) 50%);
  --drt-shrink-t-unknown: color-mix(in oklch, var(--drt-shrink-accent) 70%, black);
  color-scheme: light;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--drt-shrink-line);
}
.drt-shrink__app { height: 100%; display: grid; grid-template-columns: 190px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }

/* ---------------------------------------------------------------- nav */
.drt-shrink__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 16px; background: var(--drt-shrink-side); border-right: 1px solid var(--drt-shrink-line); border-radius: 14px 0 0 14px; }
.drt-shrink__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .drt-shrink__logo { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; background: var(--drt-shrink-accent); color: var(--drt-shrink-card); flex: none; }
  & :where(.drt-shrink__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--drt-shrink-faint); }
}
.drt-shrink__navlist { display: grid; gap: 2px; }
.drt-shrink__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 8px; color: var(--drt-shrink-mute); font-weight: 560; text-align: left; transition: background-color .15s, color .15s;
  &:hover { background: color-mix(in oklch, var(--drt-shrink-ink) 6%, transparent); color: var(--drt-shrink-ink); }
  &[aria-current="page"] { background: var(--drt-shrink-card); color: var(--drt-shrink-ink); box-shadow: inset 0 0 0 1px var(--drt-shrink-line); }
  & .drt-shrink__navn { margin-left: auto; font-style: normal; font-size: 11px; font-weight: 700; min-width: 20px; height: 18px; padding: 0 5px; border-radius: 9px; display: grid; place-items: center; background: var(--drt-shrink-accent); color: var(--drt-shrink-card); font-variant-numeric: tabular-nums; }
}
.drt-shrink__kl { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-shrink-faint); }
.drt-shrink__policy, .drt-shrink__navfoot {
  display: grid; gap: 3px; padding: 0 8px;
  & b { font: 700 16px/1.2 var(--drt-shrink-mono); letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--drt-shrink-faint); text-wrap: pretty; }
}
.drt-shrink__navfoot { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--drt-shrink-line); }
.drt-shrink__navfoot b { font: 650 13px/1.3 var(--drt-shrink-sans); letter-spacing: 0; }

/* ---------------------------------------------------------------- top */
.drt-shrink__top { grid-area: top; display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; padding: 16px 20px 12px; }
.drt-shrink__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-shrink-faint); }
.drt-shrink__title h2 { font-size: clamp(19px, 2.1cqi, 25px); font-weight: 780; letter-spacing: -.03em; line-height: 1.12; margin-top: 3px; }
.drt-shrink__h2s { font-weight: 450; color: var(--drt-shrink-mute); font-style: italic; letter-spacing: -.01em; }
.drt-shrink__ctrls { display: flex; gap: 10px; align-items: center; }
.drt-shrink__seg, .drt-shrink__mini, .drt-shrink__chips {
  display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--drt-shrink-ink) 6.5%, transparent);
  & button { height: 28px; padding: 0 12px; border-radius: 6px; font-size: 12.5px; font-weight: 600; color: var(--drt-shrink-mute); white-space: nowrap; display: flex; align-items: center; gap: 6px; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--drt-shrink-ink); }
  & button[aria-checked="true"] { background: var(--drt-shrink-ink); color: var(--drt-shrink-bg); }
  & button em { font-style: normal; font-size: 11px; opacity: .65; font-variant-numeric: tabular-nums; }
  & button i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
}
.drt-shrink__mini button { height: 24px; padding: 0 9px; font-size: 11.5px; }
.drt-shrink__clear {
  height: 30px; display: flex; align-items: center; gap: 6px; padding: 0 8px 0 12px; border-radius: 99px; font-size: 12.5px; font-weight: 620;
  background: color-mix(in oklch, var(--drt-shrink-accent) 10%, transparent); color: var(--drt-shrink-accent);
  & .drt-shrink__i { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklch, var(--drt-shrink-accent) 17%, transparent); }
}

/* ---------------------------------------------------------------- main grid */
.drt-shrink__main { grid-area: main; min-height: 0; padding: 0 20px 18px; overflow: hidden; }
.drt-shrink__view { height: 100%; }
.drt-shrink__rv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1.45fr) minmax(0, 1fr); grid-template-rows: auto minmax(0, 1.2fr) minmax(0, 1fr); grid-template-areas: "eq eq" "wf st" "cat st"; }
.drt-shrink__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-shrink-card); box-shadow: inset 0 0 0 1px var(--drt-shrink-line); overflow: hidden; }
.drt-shrink__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 11px 14px 6px;
  & h3 { font-size: 13px; font-weight: 700; }
  & h3 small { font-weight: 500; color: var(--drt-shrink-faint); margin-left: 6px; font-size: 11.5px; }
}
.drt-shrink__wfp { grid-area: wf; }
.drt-shrink__catp { grid-area: cat; }
.drt-shrink__stp { grid-area: st; }

/* equation strip, ruled like ledger paper */
.drt-shrink__eq {
  grid-area: eq; display: flex; align-items: stretch; gap: 14px; padding: 10px 16px; border-radius: 12px;
  background: repeating-linear-gradient(0deg, transparent 0 15px, var(--drt-shrink-hair) 15px 16px), var(--drt-shrink-card);
  box-shadow: inset 0 0 0 1px var(--drt-shrink-line), inset 3px 0 0 var(--drt-shrink-accent);
  & > div { display: grid; align-content: center; gap: 1px; }
  & b { font: 700 clamp(16px, 1.9cqi, 21px)/1.2 var(--drt-shrink-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & > i { font-style: normal; align-self: center; font: 400 20px/1 var(--drt-shrink-mono); color: var(--drt-shrink-faint); }
  & small { font-size: 11px; color: var(--drt-shrink-mute); font-variant-numeric: tabular-nums; }
  & .drt-shrink__eqs b { color: var(--drt-shrink-accent); }
  & .drt-shrink__eqp { margin-left: auto; padding-left: 16px; border-left: 1px solid var(--drt-shrink-line); }
  & .drt-shrink__eqp b.is-over { color: var(--drt-shrink-accent); }
  & .drt-shrink__eqp b.is-ok { color: var(--drt-shrink-good); }
  & .drt-shrink__eqk { min-width: 150px; }
}
.drt-shrink__split { display: block; height: 8px; border-radius: 4px; background: var(--drt-shrink-t-unknown); overflow: hidden; margin: 4px 0 2px; }
.drt-shrink__split i { display: block; height: 100%; width: 100%; background: var(--drt-shrink-t-damage); transform-origin: 0 50%; scale: var(--k, 0) 1; transition: scale .8s var(--drt-shrink-out); }

/* ---------------------------------------------------------------- waterfall */
.drt-shrink__box { position: relative; flex: 1; min-height: 0; margin: 0 8px 6px; }
.drt-shrink__wf {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .gl { stroke: var(--drt-shrink-hair); }
  & .ax { font: 10px var(--drt-shrink-mono); fill: var(--drt-shrink-faint); font-variant-numeric: tabular-nums; }
  & .brk { fill: var(--drt-shrink-card); stroke: var(--drt-shrink-faint); stroke-width: 1; }
  & .cn { stroke: var(--drt-shrink-faint); stroke-dasharray: 2 3; animation: drt-shrink-fade .5s calc(500ms + var(--i) * 70ms) backwards; }
  & .b { transform-box: fill-box; transition: opacity .2s, filter .2s; }
  & .b.tot { fill: var(--drt-shrink-slate); transform-origin: 50% 100%; animation: drt-shrink-rise .7s var(--drt-shrink-out) calc(var(--i) * 70ms) backwards; }
  & .b.tot.end { fill: var(--drt-shrink-good); }
  & .b.loss { fill: var(--c); transform-origin: 50% 0; animation: drt-shrink-drop .7s var(--drt-shrink-out) calc(var(--i) * 70ms) backwards; cursor: pointer; }
  & .b.loss:hover { filter: brightness(1.12) saturate(1.1); }
  &:has(.b.loss:hover) .b.loss:not(:hover) { opacity: .55; }
  & .v { font: 600 11px var(--drt-shrink-mono); fill: var(--drt-shrink-ink); font-variant-numeric: tabular-nums; animation: drt-shrink-fade .5s calc(450ms + var(--i) * 70ms) backwards; pointer-events: none; }
  & .v.l { fill: var(--drt-shrink-accent); }
  & .xl { font-size: 11px; font-weight: 600; fill: var(--drt-shrink-mute); pointer-events: none; }
  & .xs { font-size: 10px; fill: var(--drt-shrink-faint); pointer-events: none; font-variant-numeric: tabular-nums; }
  & .v.t { font-size: 9.5px; letter-spacing: -.02em; }
  & .xl.t { font-size: 10px; }
}
@keyframes drt-shrink-rise { from { scale: 1 0; } }
@keyframes drt-shrink-drop { from { scale: 1 0; } }
@keyframes drt-shrink-fade { from { opacity: 0; } }

/* ---------------------------------------------------------------- categories */
.drt-shrink__cats { flex: 1; min-height: 0; padding: 2px 14px 10px; display: grid; grid-auto-rows: minmax(21px, 1fr); gap: 2px; }
.drt-shrink__cat {
  display: grid; grid-template-columns: 132px minmax(0, 1fr) 56px 60px; gap: 10px; align-items: center; font-size: 12.5px;
