  const n = Math.round(st.sales[q] / 1e4 * .42 * (.8 + st.u * 60));
  for (let j = 0; j < n; j++) {
    const ty = TYPES[+pickW(Object.fromEntries(TYPES.map((t, i) => [i, t.w])))];
    const cat = pickW(ty.cats);
    const raw = ty.lo + Math.pow(R(), 2.1) * (ty.hi - ty.lo) * (cat === 'pt' ? 1.6 : 1);
    const date = new Date(Q[q].start + Math.floor(R() * Q[q].days) * 864e5);
    INC.push({ id: 'SH-' + String(4100 + INC.length), st: st.i, q, type: ty.k, cat, val: Math.round(raw), date, note: noteFor(ty.k, cat), by: ['K. Treloar', 'M. Hosking', 'J. Penrose', 'A. Kitto', 'S. Rowe'][Math.floor(R() * 5)], status: date < Date.UTC(2026, 6, 10) || R() < .4 ? 'rev' : 'open', brief: false });
  }
}));
/* unknown loss is found at the count: whole pounds per store and quarter, apportioned over
   categories by theft-proneness with largest remainders so every breakdown sums exactly */
const UW = { pt: 1.6, ht: 1.3, pd: .7, gd: .6, fx: 1.4, le: 1.3, pl: .8, ss: .7 };
const apportion = (total, ws) => {
  const z = ws.reduce((a, b) => a + b, 0), raw = ws.map(w => total * w / z), out = raw.map(Math.floor);
  let left = total - out.reduce((a, b) => a + b, 0);
  raw.map((v, i) => [v - Math.floor(v), i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left > 0) { out[i]++; left--; } });
  return out;
};
const U = STORES.map(st => [0, 1].map(q => {
  const tot = Math.round(st.sales[q] * st.u * (q === 1 ? 1.06 : 1));
  const parts = apportion(tot, CATS.map(c => c.mix * UW[c.k]));
  return { tot, cat: Object.fromEntries(CATS.map((c, i) => [c.k, parts[i]])) };
}));
const unknown = (s, q, cat) => cat ? U[s][q].cat[cat] : U[s][q].tot;
let per = 'h', store = -1, sortBy = 'pct';
const qs = () => per === 'h' ? [0, 1] : [+per];
const inScope = (x, s = store) => qs().includes(x.q) && (s < 0 || x.st === s);
const salesOf = (s = store) => (s < 0 ? STORES : [STORES[s]]).reduce((a, st) => a + qs().reduce((b, q) => b + st.sales[q], 0), 0);
const unknownOf = (s = store, cat) => (s < 0 ? STORES.map(x => x.i) : [s]).reduce((a, i) => a + qs().reduce((b, q) => b + unknown(i, q, cat), 0), 0);
const stockOf = (s = store) => { const q = qs()[qs().length - 1]; return (s < 0 ? STORES : [STORES[s]]).reduce((a, st) => a + Math.round(st.sales[q] * .58), 0); };
const summary = (s = store) => {
  const known = {}; TYPES.forEach(t => { known[t.k] = 0; });
  let n = 0;
  INC.forEach(x => { if (inScope(x, s)) { known[x.type] += x.val; n++; } });
  const kn = Object.values(known).reduce((a, b) => a + b, 0), un = unknownOf(s), sales = salesOf(s);
  const cnt = stockOf(s), shr = kn + un;
