};
const gbp = v => '£' + Math.round(v).toLocaleString('en-GB');
const gbpk = v => v >= 1e6 ? '£' + (v / 1e6).toFixed(2) + 'm' : '£' + (v / 1000).toFixed(v >= 1e5 ? 0 : 1) + 'k';
const pc = (v, d = 2) => (v * 100).toFixed(d) + '%';
const TOL = .012;
const TC = k => 'var(--drt-shrink-t-' + k + ')';
