/* ================================================================ waterfall */
const wf = $('.drt-shrink__wf'), wfBox = $('.drt-shrink__box');
let WF = null;
const renderWf = () => {
  const [W, H] = measure(wfBox); if (!W || !H) return;
  const S = summary();
  const steps = [{ k: 'exp', n: 'Expected', sub: 'book stock', v: S.exp, tot: true }]
    .concat(TYPES.map(t => ({ k: t.k, n: t.short, sub: INC.filter(x => inScope(x) && x.type === t.k).length + ' records', v: -S.known[t.k] })))
    .concat([{ k: 'unknown', n: 'Unknown', sub: 'found at count', v: -S.un }, { k: 'cnt', n: 'Counted', sub: 'stocktake', v: S.cnt, tot: true, end: true }]);
  /* zoomed axis: start below the counted figure, with a drawn break */
  const lo0 = S.cnt - S.shr * .9, ax = niceAxis(S.exp - lo0, 4);
  const lo = Math.floor(lo0 / ax.step) * ax.step, hi = lo + Math.ceil((S.exp - lo) * 1.05 / ax.step) * ax.step;
  const tight = W < 440, m = { l: tight ? 46 : 58, r: tight ? 4 : 10, t: 22, b: tight ? 26 : 40 }, bw = (W - m.l - m.r) / steps.length;
  const SHORT = { Expected: 'Exp.', Damage: 'Dmg', Supplier: 'Supp.', Unknown: 'Unkn.', Counted: 'Count' };
  const Y = v => m.t + (hi - v) / (hi - lo) * (H - m.t - m.b);
  let s = '';
  for (let v = lo; v <= hi + 1e-6; v += ax.step) s += '<line class="gl" x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + Y(v).toFixed(1) + '" y2="' + Y(v).toFixed(1) + '"/><text class="ax" x="' + (m.l - 8) + '" y="' + (Y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + gbpk(v) + '</text>';
  const by = H - m.b;
  s += '<path class="brk" d="M' + (m.l - 6) + ' ' + (by - 3) + ' l4 -4 l4 4 l4 -4 v6 l-4 4 l-4 -4 l-4 4z"/>';
  let run = 0;
  steps.forEach((st, i) => {
    const x = m.l + i * bw + bw * .18, w = bw * .64;
    let y0, y1, cls;
    if (st.tot) { y0 = Y(st.v); y1 = by; cls = 'b tot' + (st.end ? ' end' : ''); run = st.v; }
    else { y0 = Y(run); y1 = Y(run + st.v); cls = 'b loss'; run += st.v; }
    const h = Math.max(1.5, y1 - y0);
    s += '<rect class="' + cls + '" data-k="' + st.k + '" style="--i:' + i + ';--c:' + (st.tot ? '' : TC(st.k)) + '" x="' + x.toFixed(1) + '" y="' + y0.toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + h.toFixed(1) + '" rx="1.5"/>';
    if (i < steps.length - 1) { const yy = st.tot ? y0 : y1; s += '<line class="cn" style="--i:' + i + '" x1="' + (x + w).toFixed(1) + '" x2="' + (x + bw).toFixed(1) + '" y1="' + yy.toFixed(1) + '" y2="' + yy.toFixed(1) + '"/>'; }
    s += '<text class="v' + (st.tot ? '' : ' l') + (tight ? ' t' : '') + '" style="--i:' + i + '" x="' + (x + w / 2).toFixed(1) + '" y="' + ((st.tot ? y0 : y0) - 6).toFixed(1) + '" text-anchor="middle">' + (st.tot ? gbpk(st.v) : '−' + (tight ? (-st.v / 1000).toFixed(1) + 'k' : gbp(-st.v))) + '</text>';
    s += '<text class="xl' + (tight ? ' t' : '') + '" x="' + (x + w / 2).toFixed(1) + '" y="' + (H - m.b + 16) + '" text-anchor="middle">' + (tight && SHORT[st.n] ? SHORT[st.n] : st.n) + '</text><text class="xs" x="' + (x + w / 2).toFixed(1) + '" y="' + (H - m.b + 29) + '" text-anchor="middle">' + (bw > 74 ? st.sub : '') + '</text>';
