    const salesC = (store < 0 ? STORES : [STORES[store]]).reduce((a, st) => a + qq.reduce((b, q) => b + st.sales[q], 0), 0) * c.mix;
    const kn = INC.filter(x => inScope(x) && x.cat === c.k).reduce((a, x) => a + x.val, 0);
