});
$('.drt-shrink__brief').addEventListener('click', () => {
  const x = INC.find(i => i.id === openId); if (!x) return;
  x.brief = !x.brief; fillDrawer();
  toast(x.brief ? x.id + ' added to the loss-prevention brief (' + INC.filter(y => y.brief).length + ' items)' : x.id + ' taken off the brief');
});

/* ================================================================ wiring */
const renderAll = () => {
  $('[data-out="scope"]').textContent = store < 0 ? 'All stores' : STORES[store].n;
  const cl = $('.drt-shrink__clear'); cl.hidden = store < 0; $('[data-out="clearname"]').textContent = store < 0 ? '' : 'Showing ' + STORES[store].n;
  cl.setAttribute('aria-label', 'Clear store filter');
  $('[data-out="pername"]').textContent = per === 'h' ? 'first half · Feb–Jul' : Q[+per].n;
  renderEq(); renderWf(); renderCats(); renderStores();
  if (!$('[data-view="log"]').hidden) renderLog(); else $('[data-out="opencount"]').textContent = INC.filter(x => x.status === 'open').length;
};
const go = navInit(v => { closeDrawer(); if (v === 'log') renderLog(); else renderWf(); });
radios($('.drt-shrink__seg'), v => { per = v; renderAll(); });
radios($('.drt-shrink__mini'), v => { sortBy = v; renderStores(); });
$('.drt-shrink__clear').addEventListener('click', () => { pickStore(-1); toast('Showing all stores'); });
renderAll();
onResize(wfBox, renderWf);

css:
.drt-gaps {
  width: 100%;
  height: var(--drt-gaps-h, 680px);
  container-type: inline-size;
  container-name: drt-gaps;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-gaps-bg);
  color: var(--drt-gaps-ink);
  font: 13px/1.45 var(--drt-gaps-sans);
  accent-color: var(--drt-gaps-accent);
  -webkit-font-smoothing: antialiased;
  --drt-gaps-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-gaps-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-gaps-out: cubic-bezier(.22, 1, .36, 1);
  --drt-gaps-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-gaps-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-gaps-focus, var(--drt-gaps-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-gaps__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-gaps__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-gaps__num, & .drt-gaps__tab { font-variant-numeric: tabular-nums; }
}
.drt-gaps__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-gaps-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-gaps-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-gaps__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-gaps-tipbg, color-mix(in oklch, var(--drt-gaps-ink) 94%, var(--drt-gaps-bg)));
  color: var(--drt-gaps-tipink, var(--drt-gaps-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-gaps-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-gaps__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-gaps__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-gaps__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-gaps__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-gaps-tipbg, color-mix(in oklch, var(--drt-gaps-ink) 94%, var(--drt-gaps-bg)));
  color: var(--drt-gaps-tipink, var(--drt-gaps-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-gaps-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

.drt-gaps {
  /* re-theme with these four */
  --drt-gaps-bg: oklch(0.975 0.006 195);
  --drt-gaps-ink: oklch(0.25 0.04 222);
  --drt-gaps-accent: oklch(0.5 0.095 192);
  --drt-gaps-gap: oklch(0.6 0.2 31);
  /* derived */
  --drt-gaps-low: color-mix(in oklch, var(--drt-gaps-gap) 30%, oklch(0.8 0.15 82));
  --drt-gaps-ok: color-mix(in oklch, var(--drt-gaps-accent) 45%, oklch(0.68 0.13 150));
  --drt-gaps-card: color-mix(in oklch, var(--drt-gaps-bg), white 72%);
  --drt-gaps-line: color-mix(in oklch, var(--drt-gaps-ink) 13%, transparent);
  --drt-gaps-hair: color-mix(in oklch, var(--drt-gaps-ink) 7%, transparent);
  --drt-gaps-mute: color-mix(in oklch, var(--drt-gaps-ink) 70%, var(--drt-gaps-bg));
  --drt-gaps-faint: color-mix(in oklch, var(--drt-gaps-ink) 47%, var(--drt-gaps-bg));
  --drt-gaps-metal: color-mix(in oklch, var(--drt-gaps-ink) 16%, var(--drt-gaps-bg));
  --drt-gaps-focus: var(--drt-gaps-accent);
  color-scheme: light;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--drt-gaps-line);
}
.drt-gaps__app { height: 100%; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }

/* ---------------------------------------------------------------- bar */
.drt-gaps__bar {
  display: flex; align-items: center; gap: 8px 18px; padding: 9px 12px 9px 14px; border-radius: 14px 14px 0 0;
  background: var(--drt-gaps-ink); color: var(--drt-gaps-bg);
  --drt-gaps-focus: color-mix(in oklch, var(--drt-gaps-accent), white 45%);
}
.drt-gaps__brand {
  display: flex; align-items: center; gap: 10px;
  & .drt-gaps__logo { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; background: color-mix(in oklch, var(--drt-gaps-accent), white 18%); color: var(--drt-gaps-ink); }
  & :where(.drt-gaps__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; opacity: .62; }
}
.drt-gaps__nav {
  display: flex; gap: 2px; margin-right: auto; padding-left: 14px; border-left: 1px solid color-mix(in oklch, var(--drt-gaps-bg) 16%, transparent);
  & button { position: relative; height: 34px; display: flex; align-items: center; gap: 8px; padding: 0 12px; border-radius: 8px; font-weight: 600; color: color-mix(in oklch, var(--drt-gaps-bg) 66%, transparent); transition: color .15s, background-color .15s; }
  & button:hover { color: var(--drt-gaps-bg); background: color-mix(in oklch, var(--drt-gaps-bg) 8%, transparent); }
  & button[aria-current="page"] { color: var(--drt-gaps-bg); background: color-mix(in oklch, var(--drt-gaps-bg) 13%, transparent); }
  & em { font-style: normal; font-size: 11px; font-weight: 750; min-width: 20px; height: 18px; padding: 0 6px; border-radius: 9px; display: grid; place-items: center; background: var(--drt-gaps-gap); color: white; font-variant-numeric: tabular-nums; }
  & em:empty { display: none; }
}
.drt-gaps__round { display: flex; align-items: center; gap: 10px; }
.drt-gaps__rl { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; opacity: .55; }
.drt-gaps__seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--drt-gaps-bg) 9%, transparent);
  & button { height: 28px; padding: 0 11px; border-radius: 6px; font: 600 12.5px var(--drt-gaps-mono); color: color-mix(in oklch, var(--drt-gaps-bg) 70%, transparent); transition: color .15s, background-color .2s; }
  & button:hover { color: var(--drt-gaps-bg); }
  & button[aria-checked="true"] { background: var(--drt-gaps-bg); color: var(--drt-gaps-ink); }
  & button[aria-disabled="true"] { opacity: .38; text-decoration: line-through; text-decoration-thickness: 1px; }
  & button[aria-disabled="true"]:hover { color: color-mix(in oklch, var(--drt-gaps-bg) 70%, transparent); }
}

/* ---------------------------------------------------------------- head */
.drt-gaps__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 24px; padding: 14px 18px 12px; flex-wrap: wrap; }
.drt-gaps__eyebrow { font-size: 11px; font-weight: 620; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-gaps-faint); font-variant-numeric: tabular-nums; }
.drt-gaps__title h2 { font-size: clamp(19px, 2.2cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; margin-top: 3px; }
.drt-gaps__title h2 span { color: var(--drt-gaps-faint); font-weight: 500; }
.drt-gaps__kpis { display: grid; grid-template-columns: repeat(4, auto); gap: 0; margin: 0; }
.drt-gaps__kpi {
  display: grid; align-content: start; gap: 2px; padding: 0 18px; border-left: 1px solid var(--drt-gaps-line); min-width: 112px;
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-gaps-faint); white-space: nowrap; }
  & dd { margin: 0; display: flex; align-items: center; gap: 10px; }
  & b { font: 700 clamp(18px, 2cqi, 23px)/1.15 var(--drt-gaps-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & .drt-gaps__ks { font-size: 11.5px; color: var(--drt-gaps-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & .drt-gaps__ks b { font: inherit; font-weight: 700; letter-spacing: 0; color: var(--drt-gaps-ink); }
}
.drt-gaps__kpi--gap b { color: var(--drt-gaps-gap); }
.drt-gaps__kpi--low > dd > b { color: color-mix(in oklch, var(--drt-gaps-low) 72%, black); }
.drt-gaps__kpi--osa b.is-under { color: var(--drt-gaps-gap); }
.drt-gaps__spark {
  display: flex; align-items: flex-end; gap: 3px; height: 22px;
  & i { width: 7px; border-radius: 2px 2px 0 0; height: calc(4px + var(--v) * 18px); background: color-mix(in oklch, var(--drt-gaps-ink) 20%, transparent); transition: height .5s var(--drt-gaps-out), background-color .2s; }
  & i.on { background: var(--drt-gaps-accent); }
  & i.fut { background: none; box-shadow: inset 0 0 0 1px var(--drt-gaps-line); height: 22px; }
}

/* ---------------------------------------------------------------- main */
.drt-gaps__main { min-height: 0; padding: 0 18px 16px; }
.drt-gaps__view { height: 100%; }
.drt-gaps__sv { display: grid; gap: 12px; grid-template-columns: 206px minmax(0, 1fr) 236px; grid-template-areas: "aisles shelf det"; }
.drt-gaps__panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-gaps-card); box-shadow: inset 0 0 0 1px var(--drt-gaps-line); overflow: hidden; }
.drt-gaps__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 8px 12px; padding: 10px 12px 8px 14px; flex-wrap: wrap;
  & h3 { font-size: 13px; font-weight: 720; letter-spacing: -.01em; }
}
.drt-gaps__ap { grid-area: aisles; }
.drt-gaps__shp { grid-area: shelf; }
.drt-gaps__det { grid-area: det; }
.drt-gaps__kl { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-gaps-faint); }
.drt-gaps__mini, .drt-gaps__chips {
  display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--drt-gaps-ink) 6%, transparent);
  & button { height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 620; color: var(--drt-gaps-mute); display: flex; align-items: center; gap: 6px; white-space: nowrap; transition: color .15s, background-color .15s; }
  & button:hover { color: var(--drt-gaps-ink); }
  & button[aria-checked="true"] { background: var(--drt-gaps-card); color: var(--drt-gaps-ink); box-shadow: 0 1px 2px oklch(0.2 0.03 220 / .12), inset 0 0 0 1px var(--drt-gaps-line); }
  & em { font-style: normal; font-size: 11px; color: var(--drt-gaps-faint); font-variant-numeric: tabular-nums; }
  & i { width: 10px; height: 10px; border-radius: 2px; }
  & i.g { background: repeating-linear-gradient(-45deg, var(--drt-gaps-gap) 0 1.5px, transparent 1.5px 3.5px); box-shadow: inset 0 0 0 1px var(--drt-gaps-gap); }
  & i.l { background: var(--drt-gaps-low); }
}

/* aisle list */
.drt-gaps__scale { position: relative; display: flex; justify-content: space-between; margin: 0 14px 2px 46px; font: 9.5px var(--drt-gaps-mono); color: var(--drt-gaps-faint); }
.drt-gaps__scale span:nth-child(2) { position: absolute; right: calc(100% - (97.5 - 85) / 15 * 100%); padding-right: 4px; border-right: 1.5px solid color-mix(in oklch, var(--drt-gaps-ink) 55%, transparent); line-height: 1; color: var(--drt-gaps-mute); }
.drt-gaps__aisles { flex: 1; min-height: 0; padding: 0 6px 8px; display: grid; align-content: start; gap: 2px; }
.drt-gaps__aisle {
  position: relative; display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; grid-template-areas: "no nm nm" "no bar ct"; gap: 4px 8px; align-items: center; padding: 7px 8px 8px; border-radius: 8px; cursor: pointer;
  transition: background-color .15s;
  & .no { grid-area: no; align-self: start; width: 24px; height: 24px; border-radius: 6px; display: grid; place-items: center; font: 700 12px var(--drt-gaps-mono); background: color-mix(in oklch, var(--drt-gaps-ink) 7%, transparent); color: var(--drt-gaps-mute); }
  & .nm { grid-area: nm; font-size: 12.5px; font-weight: 580; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ct { grid-area: ct; font: 650 10.5px/1 var(--drt-gaps-mono); min-width: 44px; text-align: right; color: var(--drt-gaps-faint); font-variant-numeric: tabular-nums; }
  & .ct.has { color: var(--drt-gaps-gap); }
  & .bar { grid-area: bar; position: relative; height: 6px; border-radius: 3px; background: color-mix(in oklch, var(--drt-gaps-ink) 7%, transparent); }
  & .bar i { position: absolute; inset: 0; border-radius: inherit; background: var(--bc); transform-origin: 0 50%; scale: var(--k) 1; transition: scale .7s var(--drt-gaps-out), background-color .3s; }
  & .bar b { position: absolute; top: -3px; bottom: -3px; left: calc((97.5 - 85) / 15 * 100%); width: 1.5px; background: var(--drt-gaps-ink); opacity: .55; }
  & .pc { position: absolute; right: 8px; bottom: 12px; font: 10px var(--drt-gaps-mono); color: var(--drt-gaps-faint); display: none; }
  &:hover { background: color-mix(in oklch, var(--drt-gaps-ink) 4.5%, transparent); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--drt-gaps-accent) 11%, transparent); }
  &[aria-selected="true"] .no { background: var(--drt-gaps-accent); color: var(--drt-gaps-card); }
  &[aria-selected="true"] .nm { font-weight: 700; }
  &:focus-visible { outline-offset: -2px; }
}

/* ---------------------------------------------------------------- elevation */
.drt-gaps__ew { flex: 1; min-height: 0; padding: 2px 14px 14px; }
.drt-gaps__elev {
  --up: 10px;
  position: relative; height: 100%; min-height: 300px; min-width: 520px;
  display: grid; column-gap: 2px;
  grid-template-columns: repeat(8, minmax(0, 1fr)) var(--up) repeat(8, minmax(0, 1fr)) var(--up) repeat(8, minmax(0, 1fr));
  grid-template-rows: 18px repeat(4, minmax(0, 1fr));
  padding: 0 var(--up);
  background: linear-gradient(to right, var(--drt-gaps-metal) var(--up), transparent var(--up) calc(100% - var(--up)), var(--drt-gaps-metal) calc(100% - var(--up))) 0 18px / 100% calc(100% - 18px) no-repeat,
              linear-gradient(color-mix(in oklch, var(--drt-gaps-ink) 3.5%, transparent), color-mix(in oklch, var(--drt-gaps-ink) 3.5%, transparent)) 0 18px / 100% calc(100% - 18px) no-repeat;
  & .bay { grid-row: 1; align-self: center; text-align: center; font-size: 10px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--drt-gaps-faint); }
  & .up { grid-row: 2 / -1; background: var(--drt-gaps-metal); margin: 0 -2px; }
  & .lip { grid-column: 1 / -1; align-self: end; height: 17px; margin: 0 calc(var(--up) * -1); background: linear-gradient(color-mix(in oklch, var(--drt-gaps-metal), white 30%), var(--drt-gaps-metal)); border-bottom: 2px solid color-mix(in oklch, var(--drt-gaps-ink) 26%, var(--drt-gaps-bg)); }
  & .row { display: contents; }
  &[data-filter="gap"] .drt-gaps__cell:not(.is-gap), &[data-filter="low"] .drt-gaps__cell:not(.is-low) { opacity: .2; filter: grayscale(1); }
}
.drt-gaps__cell {
  --c: oklch(0.73 0.095 var(--h));
  position: relative; z-index: 1; min-width: 0; display: grid; grid-template-rows: minmax(0, 1fr) 17px; cursor: pointer; border-radius: 4px 4px 0 0;
  transition: opacity .3s, filter .3s, background-color .15s;
  & .packs { display: flex; align-items: flex-end; justify-content: space-evenly; gap: 2px; padding: 6px 3px 0; min-height: 0; }
  & .pk { position: relative; flex: 0 1 24px; min-width: 0; height: 86%; animation: drt-gaps-stock .55s var(--drt-gaps-out) calc(120ms + var(--i) * 16ms) backwards; }
  & .pk.is-back { opacity: .26; scale: .86; transform-origin: 50% 100%; filter: saturate(.4); }
  & .sel { position: relative; align-self: center; justify-self: start; margin-left: 3px; padding: 0 4px; height: 13px; display: flex; align-items: center; border-radius: 2px; background: white; box-shadow: 0 0 0 .5px var(--drt-gaps-line); font: 600 9.5px/1 var(--drt-gaps-mono); color: var(--drt-gaps-ink); font-variant-numeric: tabular-nums; overflow: hidden; }
  & .sel::after { content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: calc(var(--fill) * 100%); background: var(--fc, var(--drt-gaps-ok)); }
  &.is-low { --fc: var(--drt-gaps-low); }
  &.is-gap { --fc: var(--drt-gaps-gap); }
  &.is-gap .packs { margin: 6px 2px 2px; border-radius: 3px; background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--drt-gaps-gap) 20%, transparent) 0 3px, transparent 3px 7px); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--drt-gaps-gap) 75%, transparent); align-items: center; justify-content: center; padding: 0; }
  & .gm { font-size: 9.5px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--drt-gaps-gap); background: var(--drt-gaps-card); padding: 1px 4px; border-radius: 3px; }
  & .tag { position: absolute; top: 2px; right: 2px; z-index: 2; width: 15px; height: 15px; border-radius: 50%; display: grid; place-items: center; background: var(--drt-gaps-accent); color: white; box-shadow: 0 0 0 2px var(--drt-gaps-card); }
  & .tag svg { width: 9px; height: 9px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
  & .tag.ord { background: var(--drt-gaps-ink); }
  &:hover { background: color-mix(in oklch, var(--drt-gaps-ink) 6%, transparent); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--drt-gaps-accent) 14%, transparent); box-shadow: inset 0 0 0 2px var(--drt-gaps-accent); }
  &[aria-selected="true"].is-gap::before { content: ""; position: absolute; inset: 4px 0 15px; border-radius: 5px; box-shadow: 0 0 0 2px var(--drt-gaps-gap); animation: drt-gaps-ping 1.6s var(--drt-gaps-out) 3; pointer-events: none; }
