  });
  const he = Math.max(2, bot - Y(est));
  s += '<rect class="b est" style="--i:3" x="' + X(3) + '" y="' + (bot - he) + '" width="' + bw + '" height="' + he + '" rx="2"/><text class="vl" x="' + (X(3) + bw / 2) + '" y="' + (bot - he - 4) + '">~' + est + '</text><text class="xl" x="' + (X(3) + bw / 2) + '" y="' + (H - 4) + '">19:00?</text>' +
    '<rect class="hit" data-i="3" x="' + (X(3) - 8) + '" y="0" width="' + (bw + 16) + '" height="' + H + '"/>';
  dsvg.innerHTML = s;
  dsvg.setAttribute('aria-label', 'Units on shelf: ' + vals.map((v, i) => SCANS[i] + ' ' + v).join(', ') + '; about ' + est + ' expected at 19:00 if nothing is filled');
};
dsvg.addEventListener('pointermove', e => {
  const h = e.target.closest('.hit'); if (!h) { untip(); return; }
  const k = SKU[selId], i = +h.dataset.i;
  if (i === 3) { tip('<span class="drt-gaps__tt">19:00 · projected</span><b>~' + Math.max(0, Math.round(k.shelf[LIVE] - k.ros * 4)) + '</b> on shelf if nothing is filled<br>at ' + k.ros.toFixed(1) + ' sold an hour', e.clientX, e.clientY); return; }
  tip('<span class="drt-gaps__tt">' + SCANS[i] + ' scan</span><span class="drt-gaps__trow"><span>On shelf</span><b>' + k.shelf[i] + ' / ' + k.cap + '</b></span><span class="drt-gaps__trow"><span>Backroom</span><b>' + k.back[i] + '</b></span>', e.clientX, e.clientY);
});
dsvg.addEventListener('pointerleave', untip);
const fillBtn = $('[data-act="fill"]'), pickBtn = $('[data-act="pick"]');
const renderDetail = () => {
  const k = SKU[selId], st = status(k), q = k.shelf[round], back = k.back[round];
  det.classList.toggle('is-gap', st === 'gap');
  D('loc').textContent = 'Aisle ' + (k.a + 1) + ' · Bay ' + (k.b + 1) + ' · Shelf ' + (k.s + 1);
  const pill = D('pill'); pill.className = 'drt-gaps__pill ' + st; pill.textContent = st === 'gap' ? 'Gap' : st === 'low' ? 'Running low' : 'On shelf';
  D('name').textContent = k.name;
  D('sub').textContent = money(k.price) + ' · ' + k.f + ' facings · sells ' + k.ros.toFixed(1) + ' an hour';
  D('q').textContent = q; D('cap').textContent = 'of ' + k.cap + ' · ' + Math.round(q / k.cap * 100) + '% full';
  D('back').textContent = back; D('backs').textContent = back ? 'units in the back' : 'none — order needed';
  drawDay(k);
  let note;
  if (st === 'gap') note = 'Empty at the ' + SCANS[round] + ' scan. Each hour it stays empty costs about <b>' + money(lostH(k)) + '</b> in sales.';
  else { const hrs = q / k.ros, h = +SCANS[round].slice(0, 2) + hrs; note = h < 22 ? 'At ' + k.ros.toFixed(1) + ' an hour the shelf runs empty around <b>' + hm(h) + '</b>.' : 'Enough on shelf to last until close at 22:00.'; }
  if (round === LIVE && sent.has(k.id)) note += ' On the replen handheld since <b>' + sent.get(k.id) + '</b>.';
  if (round === LIVE && ordered.has(k.id)) note += ' On tomorrow’s supplier order.';
  D('note').innerHTML = note;
  const hist = round !== LIVE, why = 'Read-only: this is the ' + SCANS[round] + ' scan. Switch to 15:00 to act.';
  if (back > 0 || st === 'ok') {
    fillBtn.textContent = 'Fill from backroom' + (st !== 'ok' && back ? ' (' + Math.min(back, k.cap - q) + ')' : '');
    fillBtn.removeAttribute('aria-pressed');
    fillBtn.disabled = hist || st === 'ok';
    fillBtn.title = hist ? why : st === 'ok' ? 'More than a quarter full — nothing to fill' : 'Put ' + Math.min(back, k.cap - q) + ' units from the backroom on the shelf';
  } else {
    const on = ordered.has(k.id);
    fillBtn.textContent = on ? 'Ordered · arrives Sat 05:00' : 'Add to supplier order';
    fillBtn.setAttribute('aria-pressed', String(on));
    fillBtn.disabled = hist;
    fillBtn.title = hist ? why : on ? 'Take it off tomorrow’s order' : 'Nothing in the backroom: add to tomorrow’s order';
  }
  const can = !hist && st !== 'ok' && back > 0 && !sent.has(k.id);
  pickBtn.disabled = !can;
  pickBtn.setAttribute('aria-pressed', String(picked.has(k.id)));
  pickBtn.textContent = sent.has(k.id) && !hist ? 'On the handheld' : picked.has(k.id) ? 'On the pick list ✓' : 'Add to pick list';
  pickBtn.title = hist ? why : st === 'ok' ? 'Nothing to pick — the shelf is stocked' : back === 0 ? 'Nothing to pick — no backroom stock' : sent.has(k.id) ? 'Already sent to a colleague' : picked.has(k.id) ? 'Remove from the pick list' : 'Tick it on the pick list';
};
const doFill = k => {
  const add = Math.min(k.back[LIVE], k.cap - k.shelf[LIVE]);
  if (add <= 0) return;
  k.shelf[LIVE] += add; k.back[LIVE] -= add;
  picked.delete(k.id); sent.delete(k.id);
  return add;
};
fillBtn.addEventListener('click', () => {
  const k = SKU[selId];
  if (k.back[LIVE] === 0 && status(k, LIVE) !== 'ok') {
    if (ordered.has(k.id)) ordered.delete(k.id); else ordered.add(k.id);
    toast(ordered.has(k.id) ? k.name + ' added to tomorrow’s supplier order' : k.name + ' taken off the order');
  } else {
    const add = doFill(k); if (!add) return;
    const a = AISLES[k.a];
    toast(k.name + ': ' + add + ' units filled · aisle ' + (k.a + 1) + ' now ' + pct(stats(a.skus, LIVE).osa) + ' on shelf');
  }
  refreshCell(k, true); renderDetail(); renderAisles(); kpis(); renderPick(); filterCounts();
});
pickBtn.addEventListener('click', () => {
  const k = SKU[selId];
  if (picked.has(k.id)) picked.delete(k.id); else picked.add(k.id);
  renderDetail(); renderPick();
  toast(picked.has(k.id) ? k.name + ' ticked on the pick list' : k.name + ' unticked');
});
const filterCounts = () => { const st = stats(AISLES[aisle].skus, round); $('[data-out="fgap"]').textContent = st.gaps; $('[data-out="flow"]').textContent = st.low; };

/* ================================================================ pick list */
const tbody = $('.drt-gaps__table tbody'), allBox = $('.drt-gaps__all'), sendBtn = $('.drt-gaps__send');
const tasks = () => SKU.filter(k => status(k, LIVE) !== 'ok');
const pickable = k => k.back[LIVE] > 0 && !sent.has(k.id);
const LOCATE = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="m20 20-4.4-4.4"/></svg>';
const renderPick = () => {
  const all = tasks(), fillN = all.filter(k => k.back[LIVE] > 0).length;
  $('[data-out="pall"]').textContent = all.length;
  $('[data-out="pfill"]').textContent = fillN;
  $('[data-out="porder"]').textContent = all.length - fillN;
  let rows = all.filter(k => pfilter === 'all' || (pfilter === 'fill' ? k.back[LIVE] > 0 : k.back[LIVE] === 0));
  const key = { loc: k => k.a * 100 + k.b * 10 + k.s, name: k => k.name, fill: k => k.shelf[LIVE] / k.cap, risk: k => status(k, LIVE) === 'gap' ? lostH(k) : 0 }[psort];
  rows.sort((p, q) => { const a = key(p), b = key(q); return (typeof a === 'string' ? a.localeCompare(b) : a - b) * pdir || p.id - q.id; });
  tbody.innerHTML = rows.map(k => {
    const st = status(k, LIVE), q = k.shelf[LIVE], done = sent.has(k.id) || ordered.has(k.id);
    const can = pickable(k);
    return '<tr data-k="' + k.id + '" class="' + (done ? 'is-done' : '') + '">' +
      '<td class="c"><input type="checkbox" aria-label="Pick ' + esc(k.name) + '"' + (picked.has(k.id) ? ' checked' : '') + (can ? '' : ' disabled title="' + (sent.has(k.id) ? 'Already on the handheld' : 'No backroom stock to pick') + '"') + '></td>' +
      '<td class="mono">' + loc(k) + '</td>' +
      '<td><span class="pn">' + esc(k.name) + '</span><small>' + esc(AISLES[k.a].n) + '</small></td>' +
      '<td><span class="st ' + st + '">' + (st === 'gap' ? 'Gap' : 'Low') + '</span></td>' +
      '<td class="n mono">' + (st === 'low' ? '<span class="meter" style="--f:' + (q / k.cap).toFixed(3) + '"><i></i></span>' : '') + q + ' / ' + k.cap + '</td>' +
      '<td class="n mono">' + (k.back[LIVE] ? k.back[LIVE] : '<span class="none" title="Nothing in the backroom">0 · order</span>') + '</td>' +
      '<td class="n mono">' + (st === 'gap' ? money(lostH(k)) : '–') + '</td>' +
      '<td>' + (sent.has(k.id) ? '<span class="who">Sent ' + sent.get(k.id) + '</span> ' : ordered.has(k.id) ? '<span class="who">Ordered</span> ' : '') + '<button type="button" class="loc" data-loc="' + k.id + '">' + LOCATE + 'Locate</button></td></tr>';
  }).join('');
  const vis = rows.filter(pickable);
  allBox.checked = vis.length > 0 && vis.every(k => picked.has(k.id));
  allBox.indeterminate = !allBox.checked && vis.some(k => picked.has(k.id));
  allBox.disabled = !vis.length;
  const risk = sum(all.filter(k => status(k, LIVE) === 'gap').map(lostH));
  $('[data-out="psum"]').innerHTML = '<b>' + all.length + '</b> lines need attention · <b>' + money(risk) + '</b>/h at risk';
  const n = picked.size;
  $('[data-out="pfoot"]').innerHTML = n ? '<b>' + n + '</b> ticked · ' + sum(Array.from(picked).map(id => Math.min(SKU[id].back[LIVE], SKU[id].cap - SKU[id].shelf[LIVE]))) + ' units to carry out' : 'Tick lines with backroom stock to send them to a colleague';
  if (!sendBtn.classList.contains('is-busy')) {
    sendBtn.disabled = !n;
    sendBtn.title = n ? 'Send ' + n + ' fill tasks to the replen handheld' : 'Tick tasks to send them';
    $('[data-out="sendl"]').textContent = n ? 'Send ' + n + ' to handheld' : 'Send to handheld';
  }
};
tbody.addEventListener('change', e => {
  const cb = e.target.closest('input[type=checkbox]'); if (!cb) return;
  const id = +cb.closest('tr').dataset.k;
  if (cb.checked) picked.add(id); else picked.delete(id);
  renderPick(); if (id === selId) renderDetail();
});
tbody.addEventListener('click', e => {
  const lb = e.target.closest('[data-loc]');
  if (lb) { locate(+lb.dataset.loc); return; }
  if (e.target.closest('input, button')) return;
  const tr = e.target.closest('tr'); if (!tr) return;
  const cb = tr.querySelector('input');
  if (cb && !cb.disabled) { cb.checked = !cb.checked; cb.dispatchEvent(new Event('change', { bubbles: true })); }
  else toast(SKU[+tr.dataset.k].name + (sent.has(+tr.dataset.k) ? ' is already on the handheld' : ' has no backroom stock — it needs an order'));
});
allBox.addEventListener('change', () => {
  const rows = $$('tr', tbody).map(tr => SKU[+tr.dataset.k]).filter(pickable);
  rows.forEach(k => { if (allBox.checked) picked.add(k.id); else picked.delete(k.id); });
  renderPick(); renderDetail();
});
$$('[data-sort]').forEach(b => b.addEventListener('click', () => {
  const k = b.dataset.sort;
  if (psort === k) pdir = -pdir; else { psort = k; pdir = k === 'risk' ? -1 : 1; }
  $$('.drt-gaps__table th[aria-sort]').forEach(th => { const bb = th.querySelector('[data-sort]'); th.setAttribute('aria-sort', bb && bb.dataset.sort === psort ? (pdir > 0 ? 'ascending' : 'descending') : 'none'); });
  renderPick();
}));
radios($('.drt-gaps__pph .drt-gaps__chips'), v => { pfilter = v; renderPick(); });
sendBtn.addEventListener('click', () => {
  if (!picked.size || sendBtn.classList.contains('is-busy')) return;
  const ids = Array.from(picked);
  sendBtn.classList.add('is-busy'); sendBtn.setAttribute('aria-busy', 'true');
  $('[data-out="sendl"]').textContent = 'Sending ' + ids.length + '…';
  setTimeout(() => {
    if (!root.isConnected) return;
    const t = nowTime();
    ids.forEach(id => { sent.set(id, t); picked.delete(id); });
    sendBtn.classList.remove('is-busy'); sendBtn.removeAttribute('aria-busy');
    renderPick(); kpis(); renderDetail();
    if (view === 'shelves') renderShelf();
    toast(ids.length + (ids.length === 1 ? ' fill task' : ' fill tasks') + ' sent to the replen handheld at ' + t);
  }, RM ? 200 : 1150);
});
const locate = id => {
  const k = SKU[id];
  if (round !== LIVE) { round = LIVE; setRound(String(LIVE), true); }
  go('shelves');
  if (aisle !== k.a) { aisle = k.a; renderAisles(false); renderShelf(); header(); }
  selectSku(id, true);
  const c = cellOf(id);
  if (c) { c.classList.remove('is-flash'); void c.offsetWidth; c.classList.add('is-flash'); c.scrollIntoView({ block: 'nearest', inline: 'center' }); }
};

/* ================================================================ chrome */
const header = () => {
  const a = AISLES[aisle];
  $('[data-out="eyebrow"]').textContent = 'Friday 2 Oct · ' + SCANS[view === 'pick' ? LIVE : round] + ' scan · ' + SKU.length + ' lines';
  $('[data-out="title"]').innerHTML = view === 'pick' ? 'Pick list <span>· 15:00 scan</span>' : 'Aisle ' + (aisle + 1) + ' <span>· ' + esc(a.n) + '</span>';
};
const go = navInit(v => { view = v; $('.drt-gaps__round').hidden = v === 'pick'; header(); if (v === 'pick') renderPick(); else renderShelf(); });
const roundSeg = $('.drt-gaps__seg');
$('.drt-gaps__fut').addEventListener('click', () => toast('The 19:00 scan has not run yet — it starts at 19:00'));
const setRound = radios(roundSeg, v => {
  round = +v; kpis(); renderAisles(); renderShelf(); renderDetail(); header();
});
radios($('.drt-gaps__shp .drt-gaps__chips'), v => { filter = v; elev.dataset.filter = v; untip(); });
radios($('.drt-gaps__ap .drt-gaps__mini'), v => { order = v; renderAisles(); });
root.addEventListener('keydown', e => { if (e.key === 'Escape') untip(); });

/* ================================================================ start on the aisle with the most sales at risk */
const worst = AISLES.map(a => stats(a.skus, LIVE)).reduce((m, s, i, arr) => s.risk > arr[m].risk ? i : m, 0);
aisle = worst;
selId = AISLES[worst].skus.filter(k => status(k) === 'gap').sort((p, q) => lostH(q) - lostH(p))[0].id;
kpis(); renderAisles(false); renderShelf(); renderDetail(); header(); renderPick();

css:
.drt-basket {
  width: 100%;
  height: var(--drt-basket-h, 680px);
  container-type: inline-size;
  container-name: drt-basket;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-basket-bg);
  color: var(--drt-basket-ink);
  font: 13px/1.45 var(--drt-basket-sans);
  accent-color: var(--drt-basket-accent);
  -webkit-font-smoothing: antialiased;
  --drt-basket-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-basket-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-basket-out: cubic-bezier(.22, 1, .36, 1);
  --drt-basket-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-basket-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-basket-focus, var(--drt-basket-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-basket__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-basket__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-basket__num, & .drt-basket__tab { font-variant-numeric: tabular-nums; }
}
.drt-basket__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-basket-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-basket-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-basket__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-basket-tipbg, color-mix(in oklch, var(--drt-basket-ink) 94%, var(--drt-basket-bg)));
  color: var(--drt-basket-tipink, var(--drt-basket-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-basket-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-basket__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-basket__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-basket__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-basket__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-basket-tipbg, color-mix(in oklch, var(--drt-basket-ink) 94%, var(--drt-basket-bg)));
  color: var(--drt-basket-tipink, var(--drt-basket-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-basket-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

.drt-basket {
  /* re-theme with these four */
  --drt-basket-bg: oklch(0.205 0.022 178);
  --drt-basket-ink: oklch(0.95 0.014 105);
  --drt-basket-accent: oklch(0.8 0.125 58);
  --drt-basket-alt: oklch(0.8 0.1 168);
  /* derived */
  --drt-basket-card: color-mix(in oklch, var(--drt-basket-bg), var(--drt-basket-ink) 4.5%);
  --drt-basket-side: color-mix(in oklch, var(--drt-basket-bg), black 22%);
  --drt-basket-line: color-mix(in oklch, var(--drt-basket-ink) 12%, transparent);
  --drt-basket-hair: color-mix(in oklch, var(--drt-basket-ink) 6.5%, transparent);
  --drt-basket-mute: color-mix(in oklch, var(--drt-basket-ink) 70%, var(--drt-basket-bg));
  --drt-basket-faint: color-mix(in oklch, var(--drt-basket-ink) 46%, var(--drt-basket-bg));
  --drt-basket-pos: color-mix(in oklch, var(--drt-basket-alt), oklch(0.85 0.17 140) 40%);
  --drt-basket-neg: oklch(0.72 0.16 22);
  --drt-basket-c1: color-mix(in oklch, var(--drt-basket-accent), oklch(0.7 0.14 30) 60%);
  --drt-basket-c2: oklch(0.74 0.075 240);
  --drt-basket-c3: oklch(0.86 0.12 98);
  --drt-basket-c4: oklch(0.72 0.1 340);
  --drt-basket-c5: var(--drt-basket-accent);
  --drt-basket-c6: color-mix(in oklch, var(--drt-basket-alt), var(--drt-basket-bg) 25%);
  --drt-basket-tipbg: var(--drt-basket-ink);
  --drt-basket-tipink: var(--drt-basket-bg);
  color-scheme: dark;
  border-radius: 14px;
}
.drt-basket__app { height: 100%; display: grid; grid-template-columns: 184px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }

/* ---------------------------------------------------------------- nav */
.drt-basket__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 16px; background: var(--drt-basket-side); border-radius: 14px 0 0 14px; }
.drt-basket__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .drt-basket__logo { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; background: var(--drt-basket-accent); color: var(--drt-basket-bg); flex: none; }
  & :where(.drt-basket__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 15px; font-weight: 760; letter-spacing: -.01em; font-style: italic; }
  & small { font-size: 11px; color: var(--drt-basket-faint); }
}
.drt-basket__navlist { display: grid; gap: 2px; }
.drt-basket__navbtn {
  width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 8px; color: var(--drt-basket-mute); font-weight: 560; transition: background-color .15s, color .15s;
  &:hover { color: var(--drt-basket-ink); background: var(--drt-basket-hair); }
  &[aria-current="page"] { color: var(--drt-basket-ink); background: color-mix(in oklch, var(--drt-basket-accent) 14%, transparent); }
  &[aria-current="page"] .drt-basket__i { color: var(--drt-basket-accent); }
}
