  const nw = clamp(wEnd + +b.dataset.step, W0 + span - 1, W1);
  if (nw === wEnd) return;
  wEnd = nw; refresh(false);
}));
const setSpan = radios($('.drt-basket__seg'), v => { span = +v; if (wEnd - span + 1 < W0) wEnd = W0 + span - 1; refresh(false); });
radios($('.drt-basket__tills'), v => { till = v; refresh(false); });
const go = navInit(v => {
  view = v; header();
  if (v === 'mix') { layout(); readCols(); drawSvg(true); renderSel(); kick('rise'); }
  else { drawMults(true); drawBridge(); }
});
root.addEventListener('keydown', e => { if (e.key === 'Escape') untip(); });
onResize(plot, () => { if (view !== 'mix') return; layout(); drawSvg(); kick(); });
onResize(multsEl, () => { if (view === 'drv') { drawMults(false); drawBridge(); } });

readCols();
CUR = TX.filter(inWin);
layout(); header(); equation(); drawSvg(true); renderSel(); kick('rise');

css:
.drt-queue {
  width: 100%;
  height: var(--drt-queue-h, 680px);
  container-type: inline-size;
  container-name: drt-queue;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--drt-queue-bg);
  color: var(--drt-queue-ink);
  font: 13px/1.45 var(--drt-queue-sans);
  accent-color: var(--drt-queue-accent);
  -webkit-font-smoothing: antialiased;
  --drt-queue-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --drt-queue-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --drt-queue-out: cubic-bezier(.22, 1, .36, 1);
  --drt-queue-snap: cubic-bezier(.3, 1.4, .5, 1);
  --drt-queue-spring: linear(0, .08 2.4%, .3 6.6%, .62 12%, .9 18.5%, 1.05 25%, 1.08 30%, 1.05 37%, 1.01 47%, .997 61%, 1);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--drt-queue-focus, var(--drt-queue-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .drt-queue__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .drt-queue__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .drt-queue__num, & .drt-queue__tab { font-variant-numeric: tabular-nums; }
}
.drt-queue__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--drt-queue-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--drt-queue-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  &::-webkit-scrollbar-track { background: transparent; }
}
.drt-queue__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 132px; max-width: 270px;
  padding: 8px 10px 9px;
  border-radius: 10px;
  background: var(--drt-queue-tipbg, color-mix(in oklch, var(--drt-queue-ink) 94%, var(--drt-queue-bg)));
  color: var(--drt-queue-tipink, var(--drt-queue-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -12px oklch(0 0 0 / .5);
  opacity: 0; scale: .96; transform-origin: 0 100%;
  transition: opacity .14s, scale .22s var(--drt-queue-out);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .drt-queue__tt { display: block; font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; opacity: .68; margin-bottom: 4px; }
  & .drt-queue__trow { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; }
  & .drt-queue__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.drt-queue__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(460px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--drt-queue-tipbg, color-mix(in oklch, var(--drt-queue-ink) 94%, var(--drt-queue-bg)));
  color: var(--drt-queue-tipink, var(--drt-queue-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 18px; opacity: 0;
  transition: translate .5s var(--drt-queue-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --drt-queue-p { syntax: "<number>"; inherits: true; initial-value: 0; }
.drt-queue {
  /* re-theme with these four */
  --drt-queue-bg: oklch(0.195 0.013 255);
  --drt-queue-ink: oklch(0.96 0.006 250);
  --drt-queue-accent: oklch(0.88 0.18 128);
  --drt-queue-warn: oklch(0.7 0.18 30);
  /* derived */
  --drt-queue-amber: color-mix(in oklch, var(--drt-queue-warn), oklch(0.86 0.16 85) 65%);
  --drt-queue-card: color-mix(in oklch, var(--drt-queue-bg), var(--drt-queue-ink) 4%);
  --drt-queue-deep: color-mix(in oklch, var(--drt-queue-bg), black 25%);
  --drt-queue-line: color-mix(in oklch, var(--drt-queue-ink) 11%, transparent);
  --drt-queue-hair: color-mix(in oklch, var(--drt-queue-ink) 6%, transparent);
  --drt-queue-mute: color-mix(in oklch, var(--drt-queue-ink) 68%, var(--drt-queue-bg));
  --drt-queue-faint: color-mix(in oklch, var(--drt-queue-ink) 44%, var(--drt-queue-bg));
  --drt-queue-sco: oklch(0.78 0.09 230);
  --drt-queue-tipbg: var(--drt-queue-ink);
  --drt-queue-tipink: var(--drt-queue-bg);
  color-scheme: dark;
  border-radius: 14px;
}
.drt-queue__app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }

/* ---------------------------------------------------------------- bar */
.drt-queue__bar { display: flex; align-items: center; gap: 8px 16px; flex-wrap: wrap; padding: 10px 14px; background: var(--drt-queue-deep); border-radius: 14px 14px 0 0; border-bottom: 1px solid var(--drt-queue-line); }
.drt-queue__brand {
  display: flex; align-items: center; gap: 10px;
  & .drt-queue__logo { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: var(--drt-queue-accent); color: var(--drt-queue-deep); }
  & :where(.drt-queue__brandtx) { display: grid; line-height: 1.15; }
  & b { font-size: 14.5px; font-weight: 800; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--drt-queue-faint); }
}
.drt-queue__nav {
  display: flex; gap: 2px; padding-left: 14px; border-left: 1px solid var(--drt-queue-line); margin-right: auto;
  & button { height: 32px; display: flex; align-items: center; gap: 8px; padding: 0 12px; border-radius: 8px; font-weight: 600; color: var(--drt-queue-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--drt-queue-ink); background: var(--drt-queue-hair); }
  & button[aria-current="page"] { color: var(--drt-queue-ink); background: color-mix(in oklch, var(--drt-queue-ink) 10%, transparent); }
}
.drt-queue__clock {
  display: flex; align-items: center; gap: 9px;
  & time { font: 650 19px/1 var(--drt-queue-mono); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & .drt-queue__date { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--drt-queue-faint); }
}
.drt-queue__live { position: relative; width: 9px; height: 9px; border-radius: 50%; background: var(--drt-queue-accent); }
.drt-queue__live::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; border: 2px solid var(--drt-queue-accent); animation: drt-queue-pulse 1.8s var(--drt-queue-out) infinite; }
.drt-queue__clock[data-run="0"] .drt-queue__live { background: var(--drt-queue-faint); }
.drt-queue__clock[data-run="0"] .drt-queue__live::after { animation: none; opacity: 0; }
@keyframes drt-queue-pulse { from { scale: .6; opacity: .9; } to { scale: 1.5; opacity: 0; } }
.drt-queue__speed { display: flex; align-items: center; gap: 6px; }
.drt-queue__pause {
  width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; color: var(--drt-queue-ink); background: var(--drt-queue-hair); transition: background-color .15s;
  &:hover { background: color-mix(in oklch, var(--drt-queue-ink) 12%, transparent); }
  & .pl { display: none; fill: currentColor; stroke: none; }
  &[aria-pressed="true"] { background: var(--drt-queue-accent); color: var(--drt-queue-deep); }
  &[aria-pressed="true"] .pl { display: block; }
  &[aria-pressed="true"] .pz { display: none; }
}
.drt-queue__seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--drt-queue-hair);
  & button { height: 26px; min-width: 36px; padding: 0 8px; border-radius: 6px; font: 650 12px var(--drt-queue-mono); color: var(--drt-queue-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--drt-queue-ink); }
  & button[aria-checked="true"] { background: var(--drt-queue-ink); color: var(--drt-queue-bg); }
}

/* ---------------------------------------------------------------- main */
.drt-queue__main { min-height: 0; padding: 14px 16px 16px; }
.drt-queue__view { height: 100%; }
.drt-queue__lv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 292px; grid-template-areas: "board side"; }
.drt-queue__panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--drt-queue-card); box-shadow: inset 0 0 0 1px var(--drt-queue-line); overflow: hidden; }
.drt-queue__board { grid-area: board; }
.drt-queue__ph {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 8px 14px; flex-wrap: wrap; padding: 12px 14px 8px 16px;
  & h2 { font-size: clamp(17px, 1.9cqi, 21px); font-weight: 780; letter-spacing: -.03em; }
}
.drt-queue__sum { font-size: 12px; color: var(--drt-queue-mute); font-variant-numeric: tabular-nums; margin-top: 2px; }
.drt-queue__sum b { color: var(--drt-queue-ink); }
.drt-queue__nudge {
  display: flex; align-items: center; gap: 10px; padding: 5px 5px 5px 12px; border-radius: 10px; font-size: 12px; font-weight: 560;
  background: color-mix(in oklch, var(--drt-queue-amber) 13%, transparent); color: var(--drt-queue-amber); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--drt-queue-amber) 35%, transparent);
  transition: opacity .3s, translate .4s var(--drt-queue-out), display .4s allow-discrete;
  @starting-style { opacity: 0; translate: 0 -6px; }
  & button { height: 28px; padding: 0 12px; border-radius: 7px; background: var(--drt-queue-amber); color: var(--drt-queue-deep); font-weight: 750; font-size: 12px; white-space: nowrap; }
  & button:hover { filter: brightness(1.08); }
}
.drt-queue__lanes { flex: 1; min-height: 0; padding: 0 8px 8px; }
.drt-queue__lh, .drt-queue__lane { display: grid; grid-template-columns: 40px 148px minmax(0, 1fr) 58px 96px; column-gap: 10px; align-items: center; }
.drt-queue__lh {
  position: sticky; top: 0; z-index: 3; padding: 6px 8px; background: var(--drt-queue-card); border-bottom: 1px solid var(--drt-queue-line);
  & span { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-queue-faint); }
  & em { font-style: normal; text-transform: none; letter-spacing: 0; font-weight: 500; }
  & .r { text-align: right; }
}
.drt-queue__lane {
  position: relative; padding: 7px 8px; border-bottom: 1px solid var(--drt-queue-hair); border-radius: 8px; cursor: pointer; transition: background-color .15s, opacity .3s;
  &:hover { background: var(--drt-queue-hair); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--drt-queue-ink) 7%, transparent); }
  &:focus-visible { outline-offset: -2px; }
  & .ln { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 8px; font: 750 15px var(--drt-queue-mono); background: var(--drt-queue-hair); color: var(--drt-queue-mute); transition: background-color .3s, color .3s; }
  & .who { display: grid; line-height: 1.25; min-width: 0; }
  & .who b { font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .who small { font-size: 11px; color: var(--drt-queue-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .wt { text-align: right; font: 650 13px var(--drt-queue-mono); font-variant-numeric: tabular-nums; }
  & .wt.w1 { color: var(--drt-queue-amber); }
  & .wt.w2 { color: var(--drt-queue-warn); }
  & .act { width: 100%; height: 30px; border-radius: 8px; font-size: 12px; font-weight: 700; box-shadow: inset 0 0 0 1px var(--drt-queue-line); color: var(--drt-queue-mute); transition: background-color .15s, color .15s, box-shadow .15s; }
  & .act:hover:not(:disabled) { color: var(--drt-queue-ink); background: var(--drt-queue-hair); }
  & .act:disabled { opacity: .4; }
  & .act.go { background: var(--drt-queue-accent); color: var(--drt-queue-deep); box-shadow: none; }
  & .act.go:hover { filter: brightness(1.08); background: var(--drt-queue-accent); color: var(--drt-queue-deep); }
  &[data-st="open"] .ln, &[data-st="closing"] .ln { background: color-mix(in oklch, var(--drt-queue-accent) 18%, transparent); color: var(--drt-queue-accent); }
  &[data-st="opening"] .ln { background: color-mix(in oklch, var(--drt-queue-amber) 16%, transparent); color: var(--drt-queue-amber); }
  &[data-st="closed"] .who b { color: var(--drt-queue-faint); font-weight: 520; }
  &[data-st="closed"] .trk { opacity: .45; }
}
/* the queue track: till at the left, customers stack to the right */
.drt-queue__lane .trk {
  --step: 21px;
  position: relative; height: 28px; overflow: hidden;
  background: linear-gradient(90deg, var(--drt-queue-hair) 1px, transparent 1px) 30px 50% / var(--step) 6px repeat-x;
  & .till { position: absolute; left: 0; top: 4px; bottom: 4px; width: 8px; border-radius: 2px; background: var(--drt-queue-line); }
  & .more { position: absolute; right: 0; top: 50%; translate: 0 -50%; font: 650 10.5px var(--drt-queue-mono); color: var(--drt-queue-mute); padding: 1px 6px; border-radius: 99px; background: var(--drt-queue-card); box-shadow: 0 0 0 1px var(--drt-queue-line); }
  & .more:empty { display: none; }
  & .closed { position: absolute; left: 18px; top: 50%; translate: 0 -50%; font-size: 11px; color: var(--drt-queue-faint); }
}
.drt-queue__lane[data-st="open"] .trk .till, .drt-queue__lane[data-st="closing"] .trk .till { background: var(--drt-queue-accent); }
.drt-queue__lane[data-st="closing"] .trk .till { background: repeating-linear-gradient(0deg, var(--drt-queue-accent) 0 3px, transparent 3px 5px); }
.drt-queue__cu {
  --s: 10px;
  position: absolute; left: 14px; top: 50%; width: var(--s); height: var(--s); margin-top: calc(var(--s) / -2); border-radius: 50%;
  background: var(--drt-queue-ink); opacity: .9;
  translate: calc(12px + var(--x) * var(--step)) 0;
  transition: translate .7s var(--drt-queue-spring), background-color .4s, opacity .35s, scale .35s var(--drt-queue-out);
  @starting-style { opacity: 0; translate: calc(40px + var(--x) * var(--step)) 0; }
  &.m { --s: 12px; }
  &.l { --s: 14px; border-radius: 4px; }
  &.w1 { background: var(--drt-queue-amber); }
  &.w2 { background: var(--drt-queue-warn); }
  &.srv { --s: 18px; translate: 0 0; background: conic-gradient(var(--drt-queue-accent) calc(var(--drt-queue-p) * 1turn), color-mix(in oklch, var(--drt-queue-ink) 18%, transparent) 0); mask: radial-gradient(circle, black 26%, transparent 28% 50%, black 52%); transition: --drt-queue-p .45s linear, translate .7s var(--drt-queue-spring), opacity .35s; }
  &.sco { background: var(--drt-queue-sco); }
  &.out { opacity: 0; scale: .4; translate: -16px 0; }
}
/* self-checkout bank */
.drt-queue__lane--sco { grid-template-rows: auto auto; row-gap: 8px; }
.drt-queue__lane--sco[data-st] .ln { background: color-mix(in oklch, var(--drt-queue-sco) 18%, transparent); color: var(--drt-queue-sco); font-size: 11px; letter-spacing: .02em; }
.drt-queue__lane--sco .trk .till { background: var(--drt-queue-sco); }
.drt-queue__units { grid-column: 2 / -1; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; }
.drt-queue__unit {
  position: relative; height: 40px; display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 7px; padding: 0 9px; border-radius: 8px; text-align: left;
  background: var(--drt-queue-hair); box-shadow: inset 0 0 0 1px var(--drt-queue-line); transition: background-color .25s, box-shadow .25s;
  & .r { width: 18px; height: 18px; border-radius: 50%; background: conic-gradient(var(--drt-queue-sco) calc(var(--drt-queue-p) * 1turn), color-mix(in oklch, var(--drt-queue-ink) 14%, transparent) 0); mask: radial-gradient(circle, transparent 46%, black 50%); transition: --drt-queue-p .45s linear; }
  & > span { min-width: 0; }
  & b { font: 700 11.5px var(--drt-queue-mono); }
  & small { display: block; font-size: 10.5px; color: var(--drt-queue-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:hover { background: color-mix(in oklch, var(--drt-queue-ink) 9%, transparent); }
  &.is-idle .r { background: color-mix(in oklch, var(--drt-queue-ink) 14%, transparent); }
  &.is-help { background: color-mix(in oklch, var(--drt-queue-amber) 16%, transparent); box-shadow: inset 0 0 0 1.5px var(--drt-queue-amber); }
  &.is-help small { color: var(--drt-queue-amber); font-weight: 650; }
  &.is-help .r { background: var(--drt-queue-amber); mask: none; animation: drt-queue-blink 1s steps(2, jump-none) infinite; }
}
@keyframes drt-queue-blink { 50% { opacity: .25; } }
/* expanded lane */
.drt-queue__xp {
  grid-column: 1 / -1; display: grid; grid-template-columns: repeat(4, minmax(0, auto)) minmax(0, 1fr); gap: 6px 22px; align-items: start; padding: 10px 4px 4px 50px;
  clip-path: inset(0 0 0 0); transition: clip-path .5s var(--drt-queue-out), opacity .3s;
  @starting-style { clip-path: inset(0 0 100% 0); opacity: 0; }
  & div { display: grid; gap: 1px; }
  & dt, & .kl { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--drt-queue-faint); }
  & dd { margin: 0; font: 650 14px var(--drt-queue-mono); font-variant-numeric: tabular-nums; }
  & .ql { display: flex; flex-wrap: wrap; gap: 4px; }
  & .ql span { font: 600 10.5px var(--drt-queue-mono); padding: 2px 7px; border-radius: 99px; background: var(--drt-queue-hair); color: var(--drt-queue-mute); font-variant-numeric: tabular-nums; }
  & .ql span.w1 { color: var(--drt-queue-amber); }
  & .ql span.w2 { color: var(--drt-queue-warn); }
}

/* ---------------------------------------------------------------- side */
.drt-queue__side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; }
.drt-queue__kpis { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.drt-queue__kpi {
  display: grid; gap: 2px; padding: 9px 12px 10px; border-radius: 12px; background: var(--drt-queue-card); box-shadow: inset 0 0 0 1px var(--drt-queue-line);
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--drt-queue-faint); }
  & dd { margin: 0; display: grid; }
  & b { font: 700 22px/1.15 var(--drt-queue-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; transition: color .3s; }
  & b.is-ok { color: var(--drt-queue-accent); }
  & b.is-warn { color: var(--drt-queue-amber); }
  & b.is-bad { color: var(--drt-queue-warn); }
  & small { font-size: 11px; color: var(--drt-queue-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.drt-queue__ph2 {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 10px 12px 4px 14px;
  & h3 { font-size: 12.5px; font-weight: 700; }
  & h3 small { font-weight: 500; color: var(--drt-queue-faint); margin-left: 4px; font-size: 11px; }
}
.drt-queue__lg {
